struct AutomatedAgentChildContext {
    project_id: i64,
    run_token: String,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum GitFinalizationState {
    Working,
    Tracking,
    CommitPending,
    PushPending,
    Completed,
    Cancelled,
}

