enum AgentSessionControlAction {
    Stop,
    Interrupt,
}

#[derive(Debug)]
struct AgentChildTerminationUnproven(String);

impl std::fmt::Display for AgentChildTerminationUnproven {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(&self.0)
    }
}

impl std::error::Error for AgentChildTerminationUnproven {}

fn unproven_agent_child_termination(error: anyhow::Error, context: &str) -> anyhow::Error {
    anyhow::Error::new(AgentChildTerminationUnproven(format!(
        "{context}: {error:#}"
    )))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AgentSessionControlState {
    Running,
    StopRequested,
    Stopped,
    InterruptRequested,
    ReadyInteractive,
    Interactive,
    ResumeRequested,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum InteractiveCodexResumeMode {
    ResumeExec,
    WritableIdle,
    WritableShared,
}

impl InteractiveCodexResumeMode {
    fn resumes_exec(self) -> bool {
        self == Self::ResumeExec
    }

    fn shares_project(self) -> bool {
        self == Self::WritableShared
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum InteractiveGuardianDisposition {
    ResumeExec,
    PreserveIdleSession,
    RestoreStopped,
    PreserveSharedSession,
    RestoreStoppedShared,
}

impl InteractiveGuardianDisposition {
    fn from_handoff(mode: InteractiveCodexResumeMode, from_holder: &str) -> Self {
        if mode.resumes_exec() {
            Self::ResumeExec
        } else if mode.shares_project() {
            if is_stopped_shared_interactive_holder(from_holder) {
                Self::RestoreStoppedShared
            } else {
                Self::PreserveSharedSession
            }
        } else if from_holder.starts_with("clt-stopped-interactive-") {
            Self::RestoreStopped
        } else {
            Self::PreserveIdleSession
        }
    }

    fn holds_project_lease(self) -> bool {
        !matches!(
            self,
            Self::PreserveSharedSession | Self::RestoreStoppedShared
        )
    }

    fn guardian_holder_prefix(self) -> &'static str {
        match self {
            Self::ResumeExec => "clt-interactive-worker",
            // Keep the established holder prefixes so a newer CLT can recover
            // guardians started by an older binary.
            Self::PreserveIdleSession => "clt-idle-interactive-worker",
            Self::RestoreStopped => "clt-stopped-interactive-worker",
            Self::PreserveSharedSession => "clt-shared-interactive-worker",
            Self::RestoreStoppedShared => "clt-stopped-shared-interactive-worker",
        }
    }

    fn from_guardian_holder(holder: &str) -> Option<Self> {
        // Recognize guardians left by the brief read-only implementation so a
        // newer CLT can still recover their persisted session controls.
        if holder.starts_with("clt-stopped-readonly-interactive-worker-") {
            return Some(Self::RestoreStoppedShared);
        }
        if holder.starts_with("clt-readonly-interactive-worker-") {
            return Some(Self::PreserveSharedSession);
        }
        [
            Self::ResumeExec,
            Self::PreserveIdleSession,
            Self::RestoreStopped,
            Self::PreserveSharedSession,
            Self::RestoreStoppedShared,
        ]
        .into_iter()
        .find(|disposition| holder.starts_with(disposition.guardian_holder_prefix()))
    }

    fn guardian_process_is_proven_dead(holder: &str) -> bool {
        Self::guardian_process_id(holder)
            .is_some_and(|pid| local_process_is_running(pid) == Some(false))
    }

    fn guardian_process_id(holder: &str) -> Option<u32> {
        let disposition = Self::from_guardian_holder(holder)?;
        holder
            .strip_prefix(disposition.guardian_holder_prefix())
            .and_then(|suffix| suffix.strip_prefix('-'))
            .and_then(|suffix| suffix.split('-').next())
            .and_then(|pid| pid.parse::<u32>().ok())
    }
}

fn is_stopped_shared_interactive_holder(holder: &str) -> bool {
    holder.starts_with("clt-stopped-shared-interactive-")
        || holder.starts_with("clt-stopped-readonly-interactive-")
}

impl AgentSessionControlState {
    fn database_value(self) -> &'static str {
        match self {
            Self::Running => "running",
            Self::StopRequested => "stop_requested",
            Self::Stopped => "stopped",
            Self::InterruptRequested => "interrupt_requested",
            Self::ReadyInteractive => "ready_interactive",
            Self::Interactive => "interactive",
            Self::ResumeRequested => "resume_requested",
        }
    }

    fn from_database(value: &str) -> Result<Self> {
        match value {
            "running" => Ok(Self::Running),
            "stop_requested" => Ok(Self::StopRequested),
            "stopped" => Ok(Self::Stopped),
            "interrupt_requested" => Ok(Self::InterruptRequested),
            "ready_interactive" => Ok(Self::ReadyInteractive),
            "interactive" => Ok(Self::Interactive),
            "resume_requested" => Ok(Self::ResumeRequested),
            _ => anyhow::bail!("Unknown Codex session control state: {value}"),
        }
    }

    fn requested_action(self) -> Option<AgentSessionControlAction> {
        match self {
            Self::StopRequested => Some(AgentSessionControlAction::Stop),
            Self::InterruptRequested => Some(AgentSessionControlAction::Interrupt),
            _ => None,
        }
    }
}

fn automated_session_control_action_for_generation(
    control: &agent_store::AgentSessionControlRecord,
    child_pid: u32,
    run_token: &str,
) -> Option<AgentSessionControlAction> {
    if control.run_token.as_deref() != Some(run_token) {
        return None;
    }
    if control.child_pid == Some(child_pid) {
        return control.state.requested_action();
    }
    match control.state {
        AgentSessionControlState::Stopped => Some(AgentSessionControlAction::Stop),
        AgentSessionControlState::ReadyInteractive => Some(AgentSessionControlAction::Interrupt),
        _ => None,
    }
}

