fn next_agent_codex_setting(current: Option<&str>, choices: &[&str]) -> Option<String> {
    let current_idx = choices
        .iter()
        .position(|choice| Some(*choice) == current)
        .unwrap_or(0);
    let next = choices[(current_idx + 1) % choices.len()];
    (!next.is_empty()).then(|| next.to_string())
}

fn update_selected_tui_agent_codex_settings(
    panel: &mut TuiAgentPanel,
    active_root: &Path,
    provider: Option<String>,
    model: Option<String>,
    reasoning_effort: Option<String>,
    fast_enabled: bool,
) -> Result<bool> {
    let Some(project_id) = panel.selected_project().map(|entry| entry.project.id) else {
        return Ok(false);
    };

    let store = open_agent_store()?;
    let changed = store.set_project_codex_settings_blocking(
        project_id,
        provider.as_deref(),
        model.as_deref(),
        reasoning_effort.as_deref(),
        fast_enabled,
    )?;
    panel.refresh(active_root);
    Ok(changed)
}

fn cycle_selected_tui_agent_codex_model(
    panel: &mut TuiAgentPanel,
    active_root: &Path,
) -> Result<String> {
    let Some(project) = panel.selected_project().map(|entry| entry.project.clone()) else {
        return Ok("No registered project selected".to_string());
    };
    let store = open_agent_store()?;
    let targets = store.list_enabled_model_targets_blocking()?;
    let current_idx = project.codex_model.as_ref().and_then(|model| {
        let provider = project.codex_provider.as_deref().unwrap_or("openai");
        targets
            .iter()
            .position(|target| target.provider_id == provider && target.model_id == *model)
            .map(|index| index + 1)
    });
    let next_idx = (current_idx.unwrap_or(0) + 1) % (targets.len() + 1);
    let (provider, model, label) = if next_idx == 0 {
        (None, None, "CLT default".to_string())
    } else {
        let target = &targets[next_idx - 1];
        (
            Some(target.provider_id.clone()),
            Some(target.model_id.clone()),
            format!("{}/{}", target.provider_id, target.model_id),
        )
    };
    let changed = update_selected_tui_agent_codex_settings(
        panel,
        active_root,
        provider,
        model,
        project.codex_reasoning_effort,
        project.codex_fast_enabled,
    )?;

    if changed {
        Ok(format!("Codex model for {}: {}", project.name, label))
    } else {
        Ok(format!(
            "Project is no longer registered: {}",
            project.path.display()
        ))
    }
}

fn cycle_selected_tui_agent_codex_reasoning(
    panel: &mut TuiAgentPanel,
    active_root: &Path,
) -> Result<String> {
    let Some(project) = panel.selected_project().map(|entry| entry.project.clone()) else {
        return Ok("No registered project selected".to_string());
    };
    let reasoning = next_agent_codex_setting(
        project.codex_reasoning_effort.as_deref(),
        &AGENT_CODEX_REASONING_EFFORTS,
    );
    let label = reasoning.as_deref().unwrap_or("default").to_string();
    let changed = update_selected_tui_agent_codex_settings(
        panel,
        active_root,
        project.codex_provider,
        project.codex_model,
        reasoning,
        project.codex_fast_enabled,
    )?;

    if changed {
        Ok(format!("Codex thinking for {}: {}", project.name, label))
    } else {
        Ok(format!(
            "Project is no longer registered: {}",
            project.path.display()
        ))
    }
}

fn toggle_selected_tui_agent_codex_fast(
    panel: &mut TuiAgentPanel,
    active_root: &Path,
) -> Result<String> {
    let Some(project) = panel.selected_project().map(|entry| entry.project.clone()) else {
        return Ok("No registered project selected".to_string());
    };
    let fast_enabled = !project.codex_fast_enabled;
    let changed = update_selected_tui_agent_codex_settings(
        panel,
        active_root,
        project.codex_provider,
        project.codex_model,
        project.codex_reasoning_effort,
        fast_enabled,
    )?;

    if changed {
        Ok(format!(
            "Codex fast mode for {}: {}",
            project.name,
            if fast_enabled { "ON" } else { "OFF" }
        ))
    } else {
        Ok(format!(
            "Project is no longer registered: {}",
            project.path.display()
        ))
    }
}

fn tui_agent_panel_refresh_interval() -> Duration {
    Duration::from_secs(TUI_AGENT_PANEL_REFRESH_SECONDS)
}

fn tui_agent_log_refresh_interval() -> Duration {
    Duration::from_millis(TUI_AGENT_LOG_REFRESH_MILLIS)
}

fn tui_agent_panel_instructions() -> &'static str {
    "Up/Down selects, Enter opens/adds, Space toggles ON/OFF, Delete removes with confirmation, g cycles Git off/commit/push, m cycles the selected target, M opens Models, f toggles fast, t cycles thinking, r retries after fixing an error, l shows output. s directly stops the selected active, interactive, or fenced session; with output open it controls that exact session. With output open: i takes over a live session and c continues an idle session. Tab returns to Kanban."
}

fn parse_agent_codex_session_id(line: &str) -> Option<String> {
    line.trim()
        .strip_prefix("session id:")
        .map(str::trim)
        .filter(|session_id| !session_id.is_empty())
        .map(str::to_string)
}

fn agent_codex_session_id_from_log(path: &Path) -> Result<Option<String>> {
    let file = fs::File::open(path)
        .with_context(|| format!("Failed to open recorded agent output {path:?}"))?;

    for line in BufReader::new(file).lines().take(100) {
        if let Some(session_id) = parse_agent_codex_session_id(&line?) {
            return Ok(Some(session_id));
        }
    }

    Ok(None)
}

fn tui_agent_log_title(log_view: &TuiAgentLogView) -> String {
    let status = if log_view.is_live { "LIVE" } else { "LATEST" };
    let controls = if log_view.session_target.is_some() {
        "s/i/c controls; l/Esc closes"
    } else {
        "l/Esc closes"
    };
    format!(
        "Agent Output [{status}]: {} ({controls})",
        log_view.project_name,
    )
}

fn latest_agent_log_path(log_dir: &Path, extension: &str) -> Result<Option<PathBuf>> {
    if !log_dir.exists() {
        return Ok(None);
    }

    let mut paths = Vec::new();
    for entry in fs::read_dir(log_dir)
        .with_context(|| format!("Failed to read agent log directory {:?}", log_dir))?
    {
        let entry = entry?;
        let path = entry.path();
        if entry.file_type()?.is_file() && path.extension() == Some(OsStr::new(extension)) {
            paths.push(path);
        }
    }
    paths.sort();
    Ok(paths.pop())
}

fn preferred_recorded_agent_output_path(run: &agent_store::AgentRunRecord) -> Option<PathBuf> {
    let stdout_path = run.stdout_path.as_ref().map(PathBuf::from);
    let stdout_has_output = stdout_path
        .as_ref()
        .and_then(|path| fs::metadata(path).ok())
        .is_some_and(|metadata| metadata.len() > 0);

    if stdout_has_output {
        stdout_path
    } else {
        run.stderr_path.as_ref().map(PathBuf::from).or(stdout_path)
    }
}

fn task_supports_interactive_codex_resume(status: &str, task: &TaskEntry) -> bool {
    matches!(status, "done" | "doing") || status == "todo" && task_entry_is_blocked(task)
}

fn codex_session_task_supports_interactive_resume(
    project_root: &Path,
    session_id: &str,
) -> Result<bool> {
    let mut matches = Vec::new();
    collect_codex_session_tasks_in_board(&get_tasks_dir(project_root), session_id, &mut matches)?;
    Ok(matches.len() == 1
        && matches
            .first()
            .is_some_and(|(status, task)| task_supports_interactive_codex_resume(status, task)))
}

fn collect_codex_session_tasks_in_board(
    board_dir: &Path,
    session_id: &str,
    matches: &mut Vec<(&'static str, TaskEntry)>,
) -> Result<()> {
    for status in ["doing", "todo", "backlog", "done"] {
        let tasks = read_task_entries(board_dir, status)?;
        for task in tasks {
            if recoverable_codex_session_id_from_task_content(&task.content) == Some(session_id) {
                matches.push((status, task.clone()));
            }
            if task.has_subtasks
                && let TaskSource::Path { path, is_dir: true } = &task.source
            {
                collect_codex_session_tasks_in_board(path, session_id, matches)?;
            }
        }
    }
    Ok(())
}

fn codex_session_for_task(task: &TaskEntry) -> Option<String> {
    recoverable_codex_session_id_from_task_content(&task.content).map(str::to_string)
}

fn toggle_tui_codex_session_stop(project_id: i64, session_id: &str) -> Result<String> {
    let state_dir = ensure_agent_state_dir()?;
    toggle_tui_codex_session_stop_at(&state_dir, project_id, session_id)
}

fn toggle_tui_codex_session_stop_at(
    state_dir: &Path,
    project_id: i64,
    session_id: &str,
) -> Result<String> {
    let store = open_agent_store_at(state_dir)?;
    let Some(control) = store.session_control_blocking(project_id, session_id)? else {
        return Ok(
            "This task does not have a live or stopped Codex session to control.".to_string(),
        );
    };

    match control.state {
        AgentSessionControlState::Running => {
            let child_pid = control
                .child_pid
                .context("The Codex session is still registering its child process; try again")?;
            let run_token = control
                .run_token
                .as_deref()
                .context("The Codex session is still registering its run; try again")?;
            if store.request_session_stop_blocking(project_id, session_id, child_pid, run_token)? {
                Ok(
                    "Stopping this Codex task session; press s again once stopped to resume it."
                        .to_string(),
                )
            } else {
                Ok("The Codex session changed before it could be stopped; try again.".to_string())
            }
        }
        AgentSessionControlState::StopRequested => {
            Ok("This Codex task session is already stopping.".to_string())
        }
        AgentSessionControlState::Stopped => {
            if store.request_stopped_session_resume_blocking(
                project_id,
                session_id,
                control.run_token.as_deref(),
            )? {
                Ok("Resuming this stopped Codex task session in automated exec mode.".to_string())
            } else {
                Ok(
                    "The stopped Codex session changed before it could be resumed; try again."
                        .to_string(),
                )
            }
        }
        AgentSessionControlState::Interactive => {
            let child_pid = control
                .child_pid
                .context("The interactive Codex session is still registering; try again")?;
            let interactive_holder = control.interactive_holder.as_deref().context(
                "The interactive Codex session has no guardian identity; leave it fenced",
            )?;
            if store.request_interactive_session_stop_blocking(
                project_id,
                session_id,
                child_pid,
                interactive_holder,
            )? {
                Ok(
                    "Stopping this interactive Codex session safely; CLT will reap it and release its reservation."
                        .to_string(),
                )
            } else {
                Ok(
                    "The interactive Codex session changed before it could be stopped; try again."
                        .to_string(),
                )
            }
        }
        AgentSessionControlState::InterruptRequested
        | AgentSessionControlState::ReadyInteractive => {
            Ok("This Codex session is being used for an interactive handoff.".to_string())
        }
        AgentSessionControlState::ResumeRequested => {
            Ok("This Codex task session is already queued to resume in exec mode.".to_string())
        }
    }
}

fn prepare_tui_codex_session_interrupt(
    project_id: i64,
    session_id: &str,
) -> Result<InteractiveAgentLease> {
    let state_dir = ensure_agent_state_dir()?;
    let lease_timeout_seconds = TUI_SESSION_HANDOFF_TIMEOUT_SECONDS.max(60);
    prepare_tui_codex_session_interrupt_at(
        &state_dir,
        project_id,
        session_id,
        lease_timeout_seconds,
        Duration::from_secs(TUI_SESSION_HANDOFF_TIMEOUT_SECONDS),
    )
}

fn prepare_tui_codex_session_interrupt_at(
    state_dir: &Path,
    project_id: i64,
    session_id: &str,
    lease_timeout_seconds: u64,
    handoff_timeout: Duration,
) -> Result<InteractiveAgentLease> {
    let store = open_agent_store_at(state_dir)?;
    let control = store
        .session_control_blocking(project_id, session_id)?
        .with_context(|| {
            format!("Codex session {session_id} is not registered as running or stopped")
        })?;
    let interactive_holder = InteractiveAgentLease::holder_for_current_process();

    match control.state {
        AgentSessionControlState::Running => {
            let child_pid = control
                .child_pid
                .context("The Codex session is still registering its child process; try again")?;
            let run_token = control
                .run_token
                .as_deref()
                .context("The Codex session is still registering its run; try again")?;
            if !store.request_session_interrupt_blocking(
                project_id,
                session_id,
                child_pid,
                run_token,
                &interactive_holder,
            )? {
                anyhow::bail!(
                    "The Codex session changed before it could be interrupted; try again"
                );
            }
        }
        AgentSessionControlState::Stopped => {
            let lease = InteractiveAgentLease::try_acquire_with_holder_at(
                state_dir,
                project_id,
                &interactive_holder,
                lease_timeout_seconds,
            )?
            .context("The project became busy before the stopped Codex session could open")?;
            if !store.begin_stopped_session_interactive_blocking(
                project_id,
                session_id,
                &interactive_holder,
                control.run_token.as_deref(),
            )? {
                anyhow::bail!(
                    "The stopped Codex session changed before it could open interactively"
                );
            }
            return Ok(lease);
        }
        AgentSessionControlState::StopRequested => {
            anyhow::bail!("This Codex session is still stopping; try again when it is stopped")
        }
        AgentSessionControlState::InterruptRequested
        | AgentSessionControlState::ReadyInteractive
        | AgentSessionControlState::Interactive => {
            anyhow::bail!("This Codex session already has an interactive handoff in progress")
        }
        AgentSessionControlState::ResumeRequested => {
            anyhow::bail!("This Codex session is already queued to resume in exec mode")
        }
    }

    let mut pending_handoff =
        PendingInteractiveHandoff::new(state_dir, project_id, session_id, &interactive_holder);
    let started = Instant::now();
    loop {
        let control = store
            .session_control_blocking(project_id, session_id)?
            .with_context(|| format!("Codex session {session_id} disappeared during handoff"))?;
        match control.state {
            AgentSessionControlState::ReadyInteractive
                if control.interactive_holder.as_deref() == Some(interactive_holder.as_str()) =>
            {
                let lease =
                    InteractiveAgentLease::adopt_at(state_dir, project_id, &interactive_holder)?
                        .context(
                            "The Codex runner did not transfer its project lease for handoff",
                        )?;
                pending_handoff.disarm();
                return Ok(lease);
            }
            AgentSessionControlState::InterruptRequested => {}
            AgentSessionControlState::ResumeRequested => {
                anyhow::bail!("The automated runner could not complete the interactive handoff")
            }
            state => anyhow::bail!(
                "Codex session {session_id} entered unexpected state {} during handoff",
                state.database_value()
            ),
        }
        if started.elapsed() >= handoff_timeout {
            anyhow::bail!("Timed out waiting for the Codex runner to enter interactive mode");
        }
        thread::sleep(Duration::from_millis(50));
    }
}

fn queue_tui_codex_session_exec_resume(
    project_id: i64,
    session_id: &str,
    interactive_holder: &str,
) -> Result<()> {
    let state_dir = ensure_agent_state_dir()?;
    let store = open_agent_store_at(&state_dir)?;
    if store.cancel_session_interrupt_handoff_blocking(
        project_id,
        session_id,
        interactive_holder,
    )? {
        return Ok(());
    }
    let control = store
        .session_control_blocking(project_id, session_id)?
        .with_context(|| format!("Codex session {session_id} disappeared before exec resume"))?;
    if matches!(
        control.state,
        AgentSessionControlState::ResumeRequested | AgentSessionControlState::Running
    ) {
        Ok(())
    } else {
        anyhow::bail!(
            "Codex session {session_id} changed to {} before exec resume could be queued",
            control.state.database_value()
        )
    }
}

