fn render_tui_agent_panel(
    f: &mut ratatui::Frame<'_>,
    area: Rect,
    panel: &mut TuiAgentPanel,
    active_root: &Path,
    focused: bool,
    text_color: Color,
    c_highlight: Color,
) {
    let enabled_count = panel
        .projects
        .iter()
        .filter(|item| item.project.enabled)
        .count();
    let running_count = panel
        .projects
        .iter()
        .filter(|item| item.runtime_state.is_running())
        .count();
    let row_count = panel.row_count();
    let title = if focused {
        " Agent Projects  <<<<<< * >>>>>> "
    } else {
        " Agent Projects "
    };
    let block = Block::default()
        .title(title)
        .title(
            Line::from(vec![Span::raw(format_tui_agent_panel_top_status(
                &panel.daemon_status,
                panel.projects.len(),
                enabled_count,
                running_count,
            ))])
            .alignment(Alignment::Right),
        )
        .borders(Borders::ALL)
        .border_style(Style::default().fg(if focused {
            Color::Yellow
        } else {
            Color::Indexed(244)
        }));
    let inner_area = block.inner(area);
    f.render_widget(block, area);

    if inner_area.height == 0 || inner_area.width == 0 {
        return;
    }

    if row_count == 0 {
        f.render_widget(
            Paragraph::new("No registered projects. Run: clt agent register .")
                .style(Style::default().fg(Color::Indexed(244))),
            inner_area,
        );
        return;
    }

    let table_width = inner_area.width as usize;
    let row_viewport_height = inner_area.height.saturating_sub(2) as usize;
    panel.keep_selection_visible(row_viewport_height);
    let codex_width = agent_codex_column_width(
        &panel.projects,
        panel.current_project_registration.is_some(),
    );
    let project_width = agent_project_column_width(
        &panel.projects,
        panel.current_project_registration.as_ref(),
        table_width,
        codex_width,
    );

    let header_area = Rect {
        x: inner_area.x,
        y: inner_area.y,
        width: inner_area.width,
        height: 1,
    };
    f.render_widget(
        Paragraph::new(format_agent_project_table_header(
            table_width,
            project_width,
            codex_width,
        ))
        .style(Style::default().fg(Color::Indexed(244))),
        header_area,
    );

    if inner_area.height > 1 {
        let separator_area = Rect {
            x: inner_area.x,
            y: inner_area.y + 1,
            width: inner_area.width,
            height: 1,
        };
        f.render_widget(
            Paragraph::new("-".repeat(table_width)).style(Style::default().fg(Color::Indexed(238))),
            separator_area,
        );
    }

    if row_viewport_height == 0 {
        return;
    }

    let selected_idx = panel.state.selected();
    let highlight_style = if focused {
        Style::default().fg(Color::Black).bg(c_highlight)
    } else {
        Style::default().fg(Color::White).bg(Color::DarkGray)
    };

    for (row, idx) in (0..row_count)
        .skip(panel.scroll_offset)
        .take(row_viewport_height)
        .enumerate()
    {
        let (text, row_style) = if idx == 0 {
            if let Some(registration) = panel.current_project_registration.as_ref() {
                (
                    format_current_project_registration_row(
                        registration,
                        table_width,
                        project_width,
                        codex_width,
                    ),
                    Style::default().fg(Color::LightGreen),
                )
            } else {
                let item = &panel.projects[idx];
                (
                    format_agent_project_table_row(
                        idx,
                        item,
                        table_width,
                        project_width,
                        codex_width,
                        item.project.path == active_root,
                    ),
                    if item.displayed_problem().is_some() {
                        Style::default().fg(Color::LightRed)
                    } else if item.project.enabled {
                        Style::default().fg(text_color)
                    } else {
                        Style::default().fg(Color::Indexed(244))
                    },
                )
            }
        } else {
            let project_idx = idx - panel.project_start_index();
            let item = &panel.projects[project_idx];
            (
                format_agent_project_table_row(
                    project_idx,
                    item,
                    table_width,
                    project_width,
                    codex_width,
                    item.project.path == active_root,
                ),
                if item.displayed_problem().is_some() {
                    Style::default().fg(Color::LightRed)
                } else if item.project.enabled {
                    Style::default().fg(text_color)
                } else {
                    Style::default().fg(Color::Indexed(244))
                },
            )
        };
        let style = if Some(idx) == selected_idx {
            highlight_style
        } else {
            row_style
        };
        let item_area = Rect {
            x: inner_area.x,
            y: inner_area.y + 2 + row as u16,
            width: inner_area.width,
            height: 1,
        };
        f.render_widget(Paragraph::new(text).style(style), item_area);
    }
}

fn tui_models_instructions() -> &'static str {
    "n adds a provider. Select a non-built-in provider on the left and press x/Delete to remove it. Local endpoints discover /models automatically; r refreshes. New models start OFF: Right, Up/Down, PageUp/PageDown, Home/End, then Space chooses them. / searches model names and IDs. a manually adds an ID. f favorites; t cycles model reasoning; d sets CLT; c sets Codex. M, Tab, or Esc returns to the previous pane. API keys come only from environment variables."
}

fn provider_env_status(provider: &agent_store::AgentModelProvider) -> String {
    match provider.env_key.as_deref() {
        Some(key) => {
            let visible = std::env::var_os(key)
                .is_some_and(|value| !value.to_string_lossy().trim().is_empty());
            format!("{key}:{}", if visible { "visible" } else { "missing" })
        }
        None => "no API key".to_string(),
    }
}

fn tui_models_provider_header() -> &'static str {
    "USE TYPE    PROVIDER (ID)"
}

fn tui_models_add_provider_hint() -> &'static str {
    "[n] Add provider"
}

fn tui_models_provider_choice_prompt() -> &'static str {
    "Add provider: [1] OpenAI  [2] OpenRouter  [3] Ollama  [4] LM Studio  [5] Local/custom endpoint  [Esc] Cancel"
}

fn include_codex_default_model_target(
    store: &agent_store::TursoAgentStore,
    selected_provider_id: &str,
    codex_provider_id: Option<&str>,
    codex_model_id: Option<&str>,
    models: &mut Vec<agent_store::AgentModelTarget>,
) -> Result<()> {
    let codex_provider_id = codex_provider_id.unwrap_or("openai");
    let Some(codex_model_id) = codex_model_id else {
        return Ok(());
    };
    if selected_provider_id != codex_provider_id
        || models
            .iter()
            .any(|model| model.provider_id == codex_provider_id && model.model_id == codex_model_id)
    {
        return Ok(());
    }

    let target = agent_store::AgentModelTarget {
        provider_id: codex_provider_id.to_string(),
        model_id: codex_model_id.to_string(),
        label: codex_model_id.to_string(),
        enabled: true,
        favorite: false,
        reasoning_effort: None,
    };
    store.upsert_model_target_blocking(&target)?;
    let insertion_index = models
        .iter()
        .position(|model| !model.favorite)
        .unwrap_or(models.len());
    models.insert(insertion_index, target);
    Ok(())
}

fn tui_models_provider_row(provider: &agent_store::AgentModelProvider) -> String {
    format!(
        "{:<3} {:<7} {} ({})",
        if provider.enabled { "ON" } else { "OFF" },
        if provider.built_in {
            "BUILTIN"
        } else {
            "CUSTOM"
        },
        provider.name,
        provider.id
    )
}

fn tui_models_model_header() -> String {
    format!(
        "{:<3} {:<3} {:<3} {:<5} {:<7} {:<16} {}",
        "USE", "FAV", "CLT", "CODEX", "THINK", "MODEL", "ID"
    )
}

fn tui_model_matches_clt_default(
    defaults: &agent_store::AgentModelDefaults,
    codex_provider_id: Option<&str>,
    codex_model_id: Option<&str>,
    model: &agent_store::AgentModelTarget,
) -> bool {
    match (
        defaults.provider_id.as_deref(),
        defaults.model_id.as_deref(),
    ) {
        (Some(provider_id), Some(model_id)) => {
            provider_id == model.provider_id && model_id == model.model_id
        }
        _ => tui_model_matches_codex_default(codex_provider_id, codex_model_id, model),
    }
}

fn tui_model_matches_codex_default(
    provider_id: Option<&str>,
    model_id: Option<&str>,
    model: &agent_store::AgentModelTarget,
) -> bool {
    let provider_id = provider_id.unwrap_or("openai");
    model_id == Some(model.model_id.as_str()) && provider_id == model.provider_id
}

fn tui_models_model_row(
    model: &agent_store::AgentModelTarget,
    is_clt_default: bool,
    is_codex_default: bool,
) -> String {
    format!(
        "{:<3} {:<3} {:<3} {:<5} {:<7} {:<16} {}",
        if model.enabled { "ON" } else { "OFF" },
        if model.favorite { "YES" } else { "-" },
        if is_clt_default { "YES" } else { "-" },
        if is_codex_default { "YES" } else { "-" },
        model.reasoning_effort.as_deref().unwrap_or("system"),
        model.label,
        model.model_id
    )
}

fn render_tui_models_panel(
    f: &mut ratatui::Frame<'_>,
    area: Rect,
    panel: &mut TuiModelsPanel,
    text_color: Color,
    c_highlight: Color,
) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(38), Constraint::Percentage(62)])
        .split(area);
    let clt_default = match (
        panel.defaults.provider_id.as_deref(),
        panel.defaults.model_id.as_deref(),
    ) {
        (Some(provider), Some(model)) => format!("{provider}/{model}"),
        _ => "Codex config".to_string(),
    };
    let default_label = format!(
        " CLT default: {clt_default} | Codex: {} ",
        panel.codex_default
    );
    let provider_focused = panel.focus == TuiModelsFocus::Providers;
    let provider_block = Block::default()
        .title(if provider_focused {
            " Providers  <<<<<< * >>>>>> "
        } else {
            " Providers "
        })
        .borders(Borders::ALL)
        .border_style(Style::default().fg(if provider_focused {
            Color::Yellow
        } else {
            Color::Indexed(244)
        }));
    let provider_inner = provider_block.inner(chunks[0]);
    f.render_widget(provider_block, chunks[0]);

    if let Some(error) = panel.last_error.as_deref() {
        f.render_widget(
            Paragraph::new(error).style(Style::default().fg(Color::Red)),
            provider_inner,
        );
        return;
    }

    let add_hint_height = provider_inner.height.min(1);
    if add_hint_height > 0 {
        f.render_widget(
            Paragraph::new(tui_models_add_provider_hint())
                .style(Style::default().fg(Color::LightGreen)),
            Rect::new(
                provider_inner.x,
                provider_inner.y,
                provider_inner.width,
                add_hint_height,
            ),
        );
    }
    if provider_inner.height > add_hint_height {
        f.render_widget(
            Paragraph::new(truncate_to_width(
                tui_models_provider_header(),
                provider_inner.width as usize,
            ))
            .style(Style::default().fg(Color::Cyan)),
            Rect::new(
                provider_inner.x,
                provider_inner.y.saturating_add(add_hint_height),
                provider_inner.width,
                1,
            ),
        );
    }
    let provider_list_inner = Rect::new(
        provider_inner.x,
        provider_inner
            .y
            .saturating_add(add_hint_height)
            .saturating_add(1),
        provider_inner.width,
        provider_inner
            .height
            .saturating_sub(add_hint_height)
            .saturating_sub(1),
    );
    let provider_selected = panel.provider_state.selected();
    let provider_height = provider_list_inner.height as usize;
    panel.provider_viewport_height = provider_height;
    let provider_offset = provider_selected
        .unwrap_or(0)
        .saturating_sub(provider_height.saturating_sub(1));
    for (index, provider) in panel
        .providers
        .iter()
        .enumerate()
        .skip(provider_offset)
        .take(provider_height)
    {
        let row = tui_models_provider_row(provider);
        let style = if Some(index) == provider_selected {
            if provider_focused {
                Style::default().fg(Color::Black).bg(c_highlight)
            } else {
                Style::default().fg(Color::White).bg(Color::DarkGray)
            }
        } else if provider.enabled {
            Style::default().fg(text_color)
        } else {
            Style::default().fg(Color::Indexed(244))
        };
        f.render_widget(
            Paragraph::new(truncate_to_width(&row, provider_list_inner.width as usize))
                .style(style),
            Rect::new(
                provider_list_inner.x,
                provider_list_inner.y + (index - provider_offset) as u16,
                provider_list_inner.width,
                1,
            ),
        );
    }

    let models_focused = panel.focus == TuiModelsFocus::Models;
    let selected_provider_name = panel
        .selected_provider()
        .map(|provider| provider.name.as_str())
        .unwrap_or("No provider");
    let model_title = if panel.model_search.is_empty() {
        format!(" {selected_provider_name} Models ")
    } else {
        format!(
            " {selected_provider_name} Models  Search: {} ",
            panel.model_search
        )
    };
    let models_block = Block::default()
        .title(if models_focused {
            format!("{model_title} <<<<<< * >>>>>>")
        } else {
            model_title
        })
        .title(Line::from(default_label).alignment(Alignment::Right))
        .borders(Borders::ALL)
        .border_style(Style::default().fg(if models_focused {
            Color::Yellow
        } else {
            Color::Indexed(244)
        }));
    let models_inner = models_block.inner(chunks[1]);
    f.render_widget(models_block, chunks[1]);

    if models_inner.height > 0 {
        let detail = panel
            .selected_provider()
            .map(|provider| {
                format!(
                    "Provider: {}  Auth: {}  Endpoint: {}  [r] discover  Wire: responses",
                    provider.id,
                    provider_env_status(provider),
                    provider.base_url.as_deref().unwrap_or("Codex built-in")
                )
            })
            .unwrap_or_default();
        f.render_widget(
            Paragraph::new(truncate_to_width(&detail, models_inner.width as usize))
                .style(Style::default().fg(Color::Indexed(244))),
            Rect::new(models_inner.x, models_inner.y, models_inner.width, 1),
        );
    }
    if models_inner.height > 1 {
        let header = tui_models_model_header();
        f.render_widget(
            Paragraph::new(truncate_to_width(&header, models_inner.width as usize))
                .style(Style::default().fg(Color::Cyan)),
            Rect::new(
                models_inner.x,
                models_inner.y.saturating_add(1),
                models_inner.width,
                1,
            ),
        );
    }
    let models_list_inner = Rect::new(
        models_inner.x,
        models_inner.y.saturating_add(2),
        models_inner.width,
        models_inner.height.saturating_sub(2),
    );

    let model_selected = panel.model_state.selected();
    let models_height = models_list_inner.height as usize;
    panel.model_viewport_height = models_height;
    let visible_model_indices = panel.visible_model_indices();
    if models_list_inner.height > 0 {
        let empty_message = if panel.models.is_empty() {
            Some("No models yet. Press r to discover or a to add a model ID.".to_string())
        } else if visible_model_indices.is_empty() {
            Some(format!(
                "No models match {:?}. Press / to change or clear the search.",
                panel.model_search
            ))
        } else {
            None
        };
        if let Some(message) = empty_message {
            f.render_widget(
                Paragraph::new(message).style(Style::default().fg(Color::Yellow)),
                models_list_inner,
            );
        }
    }
    let selected_visible_position = model_selected
        .and_then(|selected| {
            visible_model_indices
                .iter()
                .position(|index| *index == selected)
        })
        .unwrap_or(0);
    let models_offset = selected_visible_position.saturating_sub(models_height.saturating_sub(1));
    for (visible_position, model_index) in visible_model_indices
        .iter()
        .enumerate()
        .skip(models_offset)
        .take(models_height)
    {
        let model = &panel.models[*model_index];
        let row = tui_models_model_row(
            model,
            tui_model_matches_clt_default(
                &panel.defaults,
                panel.codex_default_provider.as_deref(),
                panel.codex_default_model.as_deref(),
                model,
            ),
            tui_model_matches_codex_default(
                panel.codex_default_provider.as_deref(),
                panel.codex_default_model.as_deref(),
                model,
            ),
        );
        let style = if Some(*model_index) == model_selected {
            if models_focused {
                Style::default().fg(Color::Black).bg(c_highlight)
            } else {
                Style::default().fg(Color::White).bg(Color::DarkGray)
            }
        } else if model.enabled {
            Style::default().fg(text_color)
        } else {
            Style::default().fg(Color::Indexed(244))
        };
        f.render_widget(
            Paragraph::new(truncate_to_width(&row, models_list_inner.width as usize)).style(style),
            Rect::new(
                models_list_inner.x,
                models_list_inner.y + (visible_position - models_offset) as u16,
                models_list_inner.width,
                1,
            ),
        );
    }
}

fn tui_console_content<'a>(
    agent_pane: bool,
    panel: &'a TuiAgentPanel,
    log_view: Option<&'a TuiAgentLogView>,
    feedback: &'a str,
) -> (&'a str, Color) {
    if agent_pane && let Some(error) = panel.last_error.as_deref() {
        return (error, Color::Red);
    }
    if let Some(log_view) = log_view {
        return (&log_view.content, Color::Gray);
    }
    if agent_pane
        && let Some(problem) = panel
            .selected_project()
            .and_then(TuiAgentProject::displayed_problem)
    {
        return (problem, Color::LightRed);
    }

    (feedback, Color::Gray)
}

fn tui_keyboard_enhancement_flags() -> KeyboardEnhancementFlags {
    KeyboardEnhancementFlags::DISAMBIGUATE_ESCAPE_CODES
        | KeyboardEnhancementFlags::REPORT_ALL_KEYS_AS_ESCAPE_CODES
}

struct TerminalSession {
    keyboard_enhancement_enabled: bool,
    active: bool,
}

impl TerminalSession {
    fn enter(title: &str) -> Result<Self> {
        enable_raw_mode()?;
        let mut stdout = stdout();
        if let Err(err) = stdout.execute(EnterAlternateScreen) {
            let _ = disable_raw_mode();
            return Err(err.into());
        }
        if let Err(err) = stdout.execute(EnableBracketedPaste) {
            let _ = stdout.execute(LeaveAlternateScreen);
            let _ = disable_raw_mode();
            return Err(err.into());
        }

        // Request mode 2 modified-key reporting. In particular, tmux only forwards its
        // unambiguous extended key sequences when the application inside the pane asks for
        // them, which keeps Shift+Up/Down distinct from plain task navigation.
        #[cfg(not(windows))]
        if let Err(err) = stdout.execute(PushKeyboardEnhancementFlags(
            tui_keyboard_enhancement_flags(),
        )) {
            let _ = stdout.execute(DisableBracketedPaste);
            let _ = stdout.execute(LeaveAlternateScreen);
            let _ = disable_raw_mode();
            return Err(err.into());
        }
        let keyboard_enhancement_enabled = cfg!(not(windows));

        if let Err(err) = set_terminal_title(title) {
            if keyboard_enhancement_enabled {
                let _ = stdout.execute(PopKeyboardEnhancementFlags);
            }
            let _ = stdout.execute(DisableBracketedPaste);
            let _ = stdout.execute(LeaveAlternateScreen);
            let _ = disable_raw_mode();
            return Err(err);
        }

        Ok(Self {
            keyboard_enhancement_enabled,
            active: true,
        })
    }

    fn suspend(&mut self) {
        if !self.active {
            return;
        }
        if self.keyboard_enhancement_enabled {
            let _ = stdout().execute(PopKeyboardEnhancementFlags);
        }
        let _ = stdout().execute(DisableBracketedPaste);
        let _ = disable_raw_mode();
        let _ = stdout().execute(LeaveAlternateScreen);
        let _ = stdout().flush();
        self.active = false;
    }

    fn resume(&mut self, title: &str) -> Result<()> {
        if self.active {
            return Ok(());
        }
        *self = Self::enter(title)?;
        Ok(())
    }
}

impl Drop for TerminalSession {
    fn drop(&mut self) {
        self.suspend();
    }
}

fn wrap_text(text: &str, width: usize) -> String {
    if width == 0 {
        return text.to_string();
    }
    let mut result = String::new();
    let mut current_line = String::new();

    for word in text.split_whitespace() {
        // Handle words longer than the width by breaking them
        let mut word_to_add = word;
        while word_to_add.len() > width {
            if !current_line.is_empty() {
                result.push_str(&current_line);
                result.push('\n');
                current_line.clear();
            }
            let (head, tail) = word_to_add.split_at(width);
            result.push_str(head);
            result.push('\n');
            word_to_add = tail;
        }

        if current_line.is_empty() {
            current_line.push_str(word_to_add);
        } else if current_line.len() + 1 + word_to_add.len() <= width {
            current_line.push(' ');
            current_line.push_str(word_to_add);
        } else {
            result.push_str(&current_line);
            result.push('\n');
            current_line.clear();
            current_line.push_str(word_to_add);
        }
    }
    result.push_str(&current_line);
    result
}

fn wrap_input_text(text: &str, width: usize) -> String {
    if width == 0 {
        return text.to_string();
    }

    let mut result = String::new();
    let mut col = 0;

    for ch in text.chars() {
        if ch == '\n' {
            result.push(ch);
            col = 0;
            continue;
        }

        if col >= width {
            result.push('\n');
            col = 0;
        }

        result.push(ch);
        col += 1;
    }

    result
}

fn input_cursor_offset_at(text: &str, width: usize, cursor_idx: usize) -> (u16, u16) {
    if width == 0 {
        return (0, 0);
    }

    let cursor_idx = clamp_to_char_boundary(text, cursor_idx.min(text.len()));
    let mut row = 0;
    let mut col = 0;

    for ch in text[..cursor_idx].chars() {
        if ch == '\n' {
            row += 1;
            col = 0;
            continue;
        }

        if col >= width {
            row += 1;
            col = 0;
        }

        col += 1;
    }

    if col >= width {
        (0, (row + 1) as u16)
    } else {
        (col as u16, row as u16)
    }
}

fn byte_index_at_char(text: &str, char_idx: usize) -> usize {
    text.char_indices()
        .nth(char_idx)
        .map(|(idx, _)| idx)
        .unwrap_or(text.len())
}

fn input_cursor_offset_at_char(text: &str, width: usize, cursor_chars: usize) -> (usize, usize) {
    if width == 0 {
        return (0, 0);
    }

    let mut row = 0;
    let mut col = 0;

    for ch in text.chars().take(cursor_chars) {
        if ch == '\n' {
            row += 1;
            col = 0;
            continue;
        }

        if col >= width {
            row += 1;
            col = 0;
        }

        col += 1;
    }

    if col >= width {
        (0, row + 1)
    } else {
        (col, row)
    }
}

fn char_index_for_input_offset(
    text: &str,
    width: usize,
    target_row: usize,
    target_col: usize,
) -> usize {
    if width == 0 {
        return 0;
    }

    let mut row = 0;
    let mut col = 0;

    for (char_idx, ch) in text.chars().enumerate() {
        if row == target_row && col >= target_col {
            return char_idx;
        }

        if ch == '\n' {
            if row == target_row {
                return char_idx;
            }
            row += 1;
            col = 0;
            continue;
        }

        if col >= width {
            row += 1;
            col = 0;
            if row == target_row && col >= target_col {
                return char_idx;
            }
        }

        col += 1;
    }

    text.chars().count()
}

fn move_input_cursor_row(input: &mut Input, label: &str, width: usize, row_delta: isize) {
    if width == 0 {
        return;
    }

    let full_text = format!("{}{}", label, input.value());
    let label_chars = label.chars().count();
    let input_chars = input.value().chars().count();
    let cursor_chars = label_chars + input.cursor();
    let (target_col, current_row) = input_cursor_offset_at_char(&full_text, width, cursor_chars);
    let target_row = current_row.saturating_add_signed(row_delta);

    let target_chars = char_index_for_input_offset(&full_text, width, target_row, target_col);
    let input_cursor = target_chars.saturating_sub(label_chars).min(input_chars);
    input.handle(InputRequest::SetCursor(input_cursor));
}

fn handle_input_key(input: &mut Input, key: crossterm::event::KeyEvent, label: &str, width: usize) {
    let word_modifier =
        key.modifiers.contains(KeyModifiers::CONTROL) || key.modifiers.contains(KeyModifiers::ALT);

    let request = match key.code {
        KeyCode::Char('a') if key.modifiers.contains(KeyModifiers::CONTROL) => {
            Some(InputRequest::GoToStart)
        }
        KeyCode::Char('e') if key.modifiers.contains(KeyModifiers::CONTROL) => {
            Some(InputRequest::GoToEnd)
        }
        KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
            Some(InputRequest::DeleteLine)
        }
        KeyCode::Char('k') if key.modifiers.contains(KeyModifiers::CONTROL) => {
            Some(InputRequest::DeleteTillEnd)
        }
        KeyCode::Char('w') if key.modifiers.contains(KeyModifiers::CONTROL) => {
            Some(InputRequest::DeletePrevWord)
        }
        KeyCode::Char('b' | 'B') if key.modifiers.contains(KeyModifiers::ALT) => {
            Some(InputRequest::GoToPrevWord)
        }
        KeyCode::Char('f' | 'F') if key.modifiers.contains(KeyModifiers::ALT) => {
            Some(InputRequest::GoToNextWord)
        }
        KeyCode::Backspace if word_modifier => Some(InputRequest::DeletePrevWord),
        KeyCode::Delete if word_modifier => Some(InputRequest::DeleteNextWord),
        KeyCode::Left if word_modifier => Some(InputRequest::GoToPrevWord),
        KeyCode::Right if word_modifier => Some(InputRequest::GoToNextWord),
        KeyCode::Left => Some(InputRequest::GoToPrevChar),
        KeyCode::Right => Some(InputRequest::GoToNextChar),
        KeyCode::Home => Some(InputRequest::GoToStart),
        KeyCode::End => Some(InputRequest::GoToEnd),
        KeyCode::Backspace => Some(InputRequest::DeletePrevChar),
        KeyCode::Delete => Some(InputRequest::DeleteNextChar),
        KeyCode::Char(c)
            if !key.modifiers.contains(KeyModifiers::CONTROL)
                && !key.modifiers.contains(KeyModifiers::ALT) =>
        {
            Some(InputRequest::InsertChar(c))
        }
        _ => None,
    };

    if let Some(request) = request {
        input.handle(request);
        return;
    }

    match key.code {
        KeyCode::Up => move_input_cursor_row(input, label, width, -1),
        KeyCode::Down => move_input_cursor_row(input, label, width, 1),
        _ => {}
    }
}

fn clamp_to_char_boundary(text: &str, idx: usize) -> usize {
    let mut idx = idx.min(text.len());
    while idx > 0 && !text.is_char_boundary(idx) {
        idx -= 1;
    }
    idx
}

#[cfg(test)]
fn previous_char_boundary(text: &str, idx: usize) -> usize {
    let idx = clamp_to_char_boundary(text, idx);
    text[..idx]
        .char_indices()
        .last()
        .map(|(char_idx, _)| char_idx)
        .unwrap_or(0)
}

#[cfg(test)]
fn next_char_boundary(text: &str, idx: usize) -> usize {
    let idx = clamp_to_char_boundary(text, idx);
    if idx >= text.len() {
        return text.len();
    }

    text[idx..]
        .char_indices()
        .nth(1)
        .map(|(offset, _)| idx + offset)
        .unwrap_or(text.len())
}

fn board_display_name(root: &Path, board_dir: &Path) -> String {
    let tasks_dir = get_tasks_dir(root);
    if board_dir == tasks_dir {
        return project_display_name(root);
    }

    let relative = board_dir.strip_prefix(&tasks_dir).unwrap_or(board_dir);
    let parts: Vec<String> = relative
        .components()
        .filter_map(|component| match component {
            std::path::Component::Normal(name) => name.to_str().map(|name| {
                title_from_path(Path::new(strip_order_prefix(name)))
                    .split_whitespace()
                    .collect::<Vec<_>>()
                    .join(" ")
            }),
            _ => None,
        })
        .collect();

    if parts.is_empty() {
        project_display_name(root)
    } else {
        format!("{} / {}", project_display_name(root), parts.join(" / "))
    }
}

fn tui_console_block<'a>(title: &'a str, right_title: Option<&'a str>) -> Block<'a> {
    let block = Block::default().borders(Borders::ALL).title(title);

    if let Some(right_title) = right_title {
        block.title(Line::from(right_title).alignment(Alignment::Right))
    } else {
        block
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TuiCodexHandoffStage {
    WaitingForAutomatedExit,
    PreparingIdleSession,
    PreparingSharedSession,
    EnteringInteractive,
    QueueingExecResume,
    RestoringTaskControls,
}

impl TuiCodexHandoffStage {
    fn message(self) -> &'static str {
        match self {
            Self::WaitingForAutomatedExit => {
                "Requesting the automated Codex process to stop...\nWaiting for the current run to exit safely."
            }
            Self::PreparingIdleSession => {
                "Reserving the Codex session for interactive use...\nThe session will open as soon as the handoff is ready."
            }
            Self::PreparingSharedSession => {
                "Another Codex task is using this project.\nReserving this idle session for writable interactive use alongside it..."
            }
            Self::EnteringInteractive => {
                "Entering interactive Codex...\nExit Codex when you are ready to return to CLT."
            }
            Self::QueueingExecResume => {
                "Interactive Codex exited.\nReturning the same session to automated exec mode..."
            }
            Self::RestoringTaskControls => {
                "Interactive Codex exited.\nRestoring the task's Codex session controls..."
            }
        }
    }
}

fn draw_tui_codex_handoff_status<B: ratatui::backend::Backend>(
    terminal: &mut Terminal<B>,
    stage: TuiCodexHandoffStage,
) -> std::result::Result<(), B::Error> {
    terminal.draw(|frame| {
        let area = frame.area();
        let block = Block::default()
            .borders(Borders::ALL)
            .title(" Codex handoff ");
        let inner = block.inner(area);
        frame.render_widget(block, area);

        let status_height = inner.height.min(2);
        let status_area = Rect::new(
            inner.x,
            inner.y + inner.height.saturating_sub(status_height) / 2,
            inner.width,
            status_height,
        );
        frame.render_widget(
            Paragraph::new(stage.message()).alignment(Alignment::Center),
            status_area,
        );
    })?;
    Ok(())
}

fn write_tui_codex_handoff_status<W: Write>(
    output: &mut W,
    stage: TuiCodexHandoffStage,
) -> io::Result<()> {
    writeln!(output, "\n{}", stage.message())?;
    output.flush()
}

type TuiTerminal = Terminal<CrosstermBackend<std::io::Stdout>>;

fn viewed_tui_codex_session_target(
    log_view: Option<&TuiAgentLogView>,
) -> Result<TuiCodexSessionTarget> {
    let log_view = log_view.context("Open agent output with l before controlling its session")?;
    log_view.session_target.clone().context(
        "The displayed output does not identify a Codex session yet; wait for its session ID",
    )
}

fn selected_tui_agent_session_target(panel: &TuiAgentPanel) -> Result<TuiCodexSessionTarget> {
    let state_dir = ensure_agent_state_dir()?;
    selected_tui_agent_session_target_at(panel, &state_dir)
}

fn selected_tui_agent_session_target_at(
    panel: &TuiAgentPanel,
    state_dir: &Path,
) -> Result<TuiCodexSessionTarget> {
    let selected = panel
        .selected_project()
        .context("Select a registered agent project before controlling its session")?;
    let controls = open_agent_store_at(state_dir)?
        .session_controls_for_project_blocking(selected.project.id)?
        .into_iter()
        .filter(|control| control.state != AgentSessionControlState::Stopped)
        .collect::<Vec<_>>();
    let interactive = controls
        .iter()
        .filter(|control| {
            matches!(
                control.state,
                AgentSessionControlState::Interactive | AgentSessionControlState::StopRequested
            ) && control
                .interactive_holder
                .as_deref()
                .and_then(InteractiveGuardianDisposition::from_guardian_holder)
                .is_some()
        })
        .collect::<Vec<_>>();
    let control = if interactive.len() == 1 {
        interactive[0]
    } else if controls.len() == 1 {
        &controls[0]
    } else if controls.is_empty() {
        anyhow::bail!(
            "The selected project has no active or fenced Codex session to stop; open recorded output with l to control an older session"
        );
    } else {
        anyhow::bail!(
            "The selected project has multiple controllable Codex sessions; open the intended output with l before pressing s"
        );
    };

    Ok(TuiCodexSessionTarget::new(
        &selected.project,
        control.codex_session_id.clone(),
    ))
}

fn run_tui_codex_session_interrupt(
    terminal: &mut TuiTerminal,
    terminal_session: &mut TerminalSession,
    return_title: &str,
    target: &TuiCodexSessionTarget,
    label: &str,
) -> Result<String> {
    draw_tui_codex_handoff_status(terminal, TuiCodexHandoffStage::WaitingForAutomatedExit)?;
    let interactive_lease =
        prepare_tui_codex_session_interrupt(target.project_id, &target.session_id)?;

    let _ = draw_tui_codex_handoff_status(terminal, TuiCodexHandoffStage::EnteringInteractive);
    terminal_session.suspend();
    let _ =
        write_tui_codex_handoff_status(&mut stdout(), TuiCodexHandoffStage::EnteringInteractive);
    let provisional_holder = interactive_lease.holder.clone();
    let resume_result = resume_codex_session_interactively(
        &target.project_path,
        target.project_id,
        &target.session_id,
        &provisional_holder,
        InteractiveCodexResumeMode::ResumeExec,
    );
    let _ = write_tui_codex_handoff_status(&mut stdout(), TuiCodexHandoffStage::QueueingExecResume);
    let guardian_completed = resume_result.as_ref().is_ok_and(|status| status.success());
    let queue_result = if guardian_completed {
        Ok(())
    } else {
        queue_tui_codex_session_exec_resume(
            target.project_id,
            &target.session_id,
            &provisional_holder,
        )
    };
    let release_result = interactive_lease.release();
    let worker_result = if guardian_completed {
        Ok(None)
    } else if queue_result.is_ok() {
        spawn_agent_session_resume_worker(
            &target.project_path,
            target.project_id,
            &target.session_id,
        )
        .map(Some)
    } else {
        Ok(None)
    };
    terminal_session.resume(return_title)?;
    terminal.clear()?;

    let interactive_summary = match resume_result {
        Ok(status) if status.success() => {
            format!("Returned from interactive Codex for {label}.")
        }
        Ok(status) => format!("Interactive Codex exited with {status}."),
        Err(error) => format!("Interactive Codex error: {error}."),
    };
    let supervision_log = if guardian_completed {
        agent_state_dir().ok().map(|state_dir| {
            agent_session_resume_worker_log_path(&state_dir, target.project_id, &target.session_id)
                .display()
                .to_string()
        })
    } else {
        worker_result
            .as_ref()
            .ok()
            .and_then(|path| path.as_ref())
            .map(|path| path.display().to_string())
    };
    let mut followup_errors = Vec::new();
    if let Err(error) = queue_result {
        followup_errors.push(format!("could not queue exact exec resume: {error}"));
    }
    if let Err(error) = release_result {
        followup_errors.push(format!("could not release the interactive lease: {error}"));
    }
    if let Err(error) = worker_result {
        followup_errors.push(format!(
            "could not start the exact-session resume worker: {error}"
        ));
    }

    Ok(if followup_errors.is_empty() {
        match supervision_log {
            Some(log) => format!(
                "{interactive_summary} The same session is queued and supervised for automated exec resume (worker log: {log})."
            ),
            None => interactive_summary,
        }
    } else {
        format!("{interactive_summary} CLT {}", followup_errors.join("; "))
    })
}

fn run_tui_codex_session_continue(
    terminal: &mut TuiTerminal,
    terminal_session: &mut TerminalSession,
    return_title: &str,
    target: &TuiCodexSessionTarget,
    label: &str,
    shares_project: bool,
    require_resumable_task: bool,
) -> Result<String> {
    draw_tui_codex_handoff_status(
        terminal,
        if shares_project {
            TuiCodexHandoffStage::PreparingSharedSession
        } else {
            TuiCodexHandoffStage::PreparingIdleSession
        },
    )?;
    let stopped_control = tui_stopped_codex_session_control(target.project_id, &target.session_id)?;
    let restore_stopped = stopped_control.is_some();
    let (interactive_lease, provisional_holder) = if shares_project {
        (
            None,
            InteractiveAgentLease::holder_for_shared_session(restore_stopped),
        )
    } else {
        let lease = InteractiveAgentLease::try_acquire_idle(target.project_id, restore_stopped)?
            .context(
                "Another Codex task began using this project; press c again to open this session alongside it",
            )?;
        let holder = lease.holder.clone();
        (Some(lease), holder)
    };
    let stopped_run_token = stopped_control
        .as_ref()
        .and_then(|control| control.run_token.as_deref());
    let reservation_result = if shares_project {
        reserve_tui_shared_codex_session_interactive(
            target.project_id,
            &target.session_id,
            &provisional_holder,
            stopped_run_token,
        )
    } else {
        reserve_tui_idle_codex_session_interactive(
            target.project_id,
            &target.session_id,
            &provisional_holder,
            stopped_run_token,
        )
    };
    if !reservation_result.as_ref().is_ok_and(|reserved| *reserved) {
        let release_result = interactive_lease.map_or(Ok(()), InteractiveAgentLease::release);
        return match (reservation_result, release_result) {
            (Ok(false), Ok(())) if shares_project => anyhow::bail!(
                "The active project run or selected session changed before shared Codex could open; try again"
            ),
            (Ok(false), Ok(())) => {
                anyhow::bail!(
                    "This Codex session became busy before it could be reserved; try again"
                )
            }
            (Err(error), Ok(())) => Err(error),
            (Ok(false), Err(error)) => Err(error)
                .context("The Codex session changed, and its project lease could not be released"),
            (Err(reserve_error), Err(release_error)) => Err(reserve_error).context(format!(
                "The project lease also could not be released: {release_error}"
            )),
            (Ok(true), _) => unreachable!(),
        };
    }

    if require_resumable_task {
        let task_is_resumable = codex_session_task_supports_interactive_resume(
            &target.project_path,
            &target.session_id,
        );
        if !task_is_resumable.as_ref().is_ok_and(|resumable| *resumable) {
            let cancel_result = cancel_tui_idle_codex_session_interactive(
                target.project_id,
                &target.session_id,
                &provisional_holder,
            );
            let release_result = interactive_lease.map_or(Ok(()), InteractiveAgentLease::release);
            return match (task_is_resumable, cancel_result, release_result) {
                (Ok(false), Ok(true), Ok(())) => anyhow::bail!(
                    "This task changed before its Codex session could open; c is only available from Done, Doing, or currently blocked Todo tasks"
                ),
                (Err(error), Ok(true), Ok(())) => Err(error)
                    .context("Unable to revalidate the Codex task before interactive resume"),
                (task, cancel, release) => anyhow::bail!(
                    "Unable to open the Codex task safely (task: {}; reservation: {}; lease: {})",
                    task.map(|_| "changed".to_string())
                        .unwrap_or_else(|error| error.to_string()),
                    cancel
                        .map(|cancelled| if cancelled {
                            "released"
                        } else {
                            "still fenced"
                        }
                        .to_string())
                        .unwrap_or_else(|error| error.to_string()),
                    release
                        .map(|()| "released".to_string())
                        .unwrap_or_else(|error| error.to_string()),
                ),
            };
        }
    }

    let _ = draw_tui_codex_handoff_status(terminal, TuiCodexHandoffStage::EnteringInteractive);
    terminal_session.suspend();
    let _ =
        write_tui_codex_handoff_status(&mut stdout(), TuiCodexHandoffStage::EnteringInteractive);
    let resume_result = resume_codex_session_interactively(
        &target.project_path,
        target.project_id,
        &target.session_id,
        &provisional_holder,
        if shares_project {
            InteractiveCodexResumeMode::WritableShared
        } else {
            InteractiveCodexResumeMode::WritableIdle
        },
    );
    let _ =
        write_tui_codex_handoff_status(&mut stdout(), TuiCodexHandoffStage::RestoringTaskControls);
    let guardian_completed = resume_result.as_ref().is_ok_and(|status| status.success());
    let cancel_result = if guardian_completed {
        Ok(())
    } else {
        match cancel_tui_idle_codex_session_interactive(
            target.project_id,
            &target.session_id,
            &provisional_holder,
        ) {
            Ok(true) => Ok(()),
            Ok(false) => Err(anyhow::anyhow!(
                "the guardian-owned session reservation remains fenced"
            )),
            Err(error) => Err(error),
        }
    };
    let release_result = interactive_lease.map_or(Ok(()), InteractiveAgentLease::release);
    terminal_session.resume(return_title)?;
    terminal.clear()?;

    Ok(match (resume_result, cancel_result, release_result) {
        (Ok(status), Ok(()), Ok(())) if status.success() => {
            format!("Returned from Codex session for {label}; press c to open it again")
        }
        (Ok(status), Ok(()), Ok(())) => format!("Codex session exited with status {status}"),
        (Err(error), Ok(()), Ok(())) => format!("Error: {error}"),
        (resume_result, cancel_result, release_result) => format!(
            "Codex interactive cleanup was incomplete (session: {}; reservation: {}; lease: {})",
            resume_result
                .map(|status| status.to_string())
                .unwrap_or_else(|error| error.to_string()),
            cancel_result
                .map(|()| "released".to_string())
                .unwrap_or_else(|error| error.to_string()),
            release_result
                .map(|()| "released".to_string())
                .unwrap_or_else(|error| error.to_string()),
        ),
    })
}

fn tui_view(root: &Path) -> Result<PathBuf> {
    tui_view_with_active_board(root, true)
}

fn tui_view_without_active_board(root: &Path) -> Result<PathBuf> {
    tui_view_with_active_board(root, false)
}

fn tui_view_with_active_board(root: &Path, start_with_active_board: bool) -> Result<PathBuf> {
    // Setup terminal
    let title = app_title(root);
    let mut terminal_session = TerminalSession::enter(&title)?;
    let mut terminal = Terminal::new(CrosstermBackend::new(stdout()))?;
    let mut active_root = root.to_path_buf();
    let mut board_stack = if start_with_active_board {
        vec![get_tasks_dir(&active_root)]
    } else {
        Vec::new()
    };

    let start_state = tui_start_state(start_with_active_board);
    let mut active_board = start_state.active_board;
    let mut current_mode = Mode::View;
    let mut task_input = TaskInput::default();
    let mut feedback_buffer = start_state.feedback_buffer;
    let mut archive_view = false;
    let mut backlog_visible = false;
    let mut current_pane = start_state.current_pane;
    let mut models_return_pane = tui_models_return_pane(current_pane);
    let mut agent_panel = TuiAgentPanel::new(&active_root);
    let mut task_agent_session_states = TaskAgentSessionStates::default();
    let mut models_panel = TuiModelsPanel::new();
    let mut model_input: Option<TuiModelInput> = None;
    let mut awaiting_model_provider_choice = false;
    let mut pending_agent_project_removal: Option<TuiAgentProjectRemoval> = None;
    let mut agent_panel_refresh = TuiAgentPanelRefreshWorker::new();
    let mut last_agent_panel_refresh = Instant::now();
    agent_panel_refresh.request(&active_root);
    let mut agent_log_view: Option<TuiAgentLogView> = None;
    let mut last_agent_log_refresh = Instant::now();

    let mut selected_board = TODO_BOARD_INDEX;
    let mut editing_task_idx: Option<usize> = None;
    let mut subtask_parent: Option<(usize, TaskEntry)> = None;
    let mut board_states = [
        ListState::default(),
        ListState::default(),
        ListState::default(),
        ListState::default(),
    ];
    let mut board_scroll_offsets = [0usize; 4];
    let mut archive_state = ListState::default();
    let mut archive_scroll_offset = 0usize;

    let statuses = TASK_STATUSES;
    let titles = ["To Do", "Doing", "Done", "Backlog"];
    // let c_1 = Color::LightCyan;
    // let c_2 = Color::LightGreen;
    // let c_3 = Color::LightMagenta;
    let c_1 = Color::Indexed(110);
    let c_2 = Color::Indexed(108);
    let c_3 = Color::Indexed(139);
    let c_backlog = Color::Indexed(244);
    let text_color = Color::Indexed(248); //Color::DarkGray;
    let c_highlight = Color::Indexed(221);
    let colors = [c_1, c_2, c_3, c_backlog];

    loop {
        if !active_board && current_pane == TuiPane::Tasks {
            current_pane = TuiPane::AgentProjects;
            archive_view = false;
        }

        let board_dir = board_stack
            .last()
            .cloned()
            .unwrap_or_else(|| get_tasks_dir(&active_root));
        if active_board {
            if archive_view {
                normalize_archive_selection_in_board(&board_dir, &mut archive_state);
            } else {
                normalize_board_selections_in_board(&board_dir, &statuses, &mut board_states);
            }
        }

        if let Some(refresh) = agent_panel_refresh.try_result() {
            if refresh.active_root == active_root {
                let selected_row = agent_panel.selected_row_identity();
                agent_panel.apply_refresh_result(
                    &active_root,
                    selected_row,
                    refresh.panel_snapshot,
                );
                if let Ok(states) = refresh.task_session_states {
                    task_agent_session_states = states;
                }
                if current_pane == TuiPane::AgentProjects {
                    sync_open_tui_agent_log_view(&agent_panel, &mut agent_log_view);
                } else if current_pane == TuiPane::Tasks && active_board && !archive_view {
                    let selected_task = selected_task_entry_in_board(
                        &board_dir,
                        statuses[selected_board],
                        &board_states[selected_board],
                    )
                    .map(|(_, task)| task);
                    sync_open_tui_task_log_view(
                        &mut agent_panel,
                        &active_root,
                        statuses[selected_board],
                        selected_task.as_ref(),
                        &mut agent_log_view,
                    );
                }
            } else {
                last_agent_panel_refresh = Instant::now()
                    .checked_sub(tui_agent_panel_refresh_interval())
                    .unwrap_or_else(Instant::now);
            }
        }
        if last_agent_panel_refresh.elapsed() >= tui_agent_panel_refresh_interval()
            && agent_panel_refresh.request(&active_root)
        {
            last_agent_panel_refresh = Instant::now();
        }
        if last_agent_log_refresh.elapsed() >= tui_agent_log_refresh_interval() {
            if let Some(log_view) = agent_log_view.as_mut()
                && let Err(err) = log_view.refresh()
            {
                log_view.content = format!("Error refreshing agent output: {err}");
            }
            last_agent_log_refresh = Instant::now();
        }

        terminal.draw(|f| {
            let size = f.area();
            let board_title = if active_board {
                board_display_name(&active_root, &board_dir)
            } else {
                "No Active Board".to_string()
            };
            let (console_title, console_right_title) = if let Some(log_view) = agent_log_view.as_ref() {
                (tui_agent_log_title(log_view), None)
            } else if current_pane == TuiPane::AgentProjects {
                ("Agent Projects Console".to_string(), None)
            } else if current_pane == TuiPane::Models {
                ("Models Console".to_string(), None)
            } else if archive_view {
                (format!("{board_title} Archive Console"), None)
            } else if !backlog_visible {
                let backlog_count = read_task_entries(&board_dir, "backlog")
                    .map(|entries| entries.len())
                    .unwrap_or(0);
                (
                    format!("{board_title} Console"),
                    Some(format!(" Backlog: {backlog_count} [B] ")),
                )
            } else {
                (format!("{board_title} Console"), None)
            };

            // Calculate input height if in Input or Edit mode
            let input_height = if model_input.is_some() {
                3
            } else if matches!(current_mode, Mode::Input) || matches!(current_mode, Mode::Edit) {
                    let label = if matches!(current_mode, Mode::Input) {
                        if subtask_parent.is_some() {
                            " Add Subtask: "
                        } else {
                            " Add Task: "
                        }
                    } else {
                        " Edit Task: "
                    };
                    let display_value = task_input.display_value();
                    let full_text = format!("{}{}", label, display_value);
                    // Subtract 2 for the borders of the block
                    let available_width = size.width.saturating_sub(2) as usize;
                    let wrapped = wrap_input_text(&full_text, available_width);
                    let lines = wrapped.lines().count();
                    let cursor_idx =
                        label.len() + byte_index_at_char(&display_value, task_input.display_cursor());
                    let cursor_row =
                        input_cursor_offset_at(&full_text, available_width, cursor_idx).1 as usize;
                    // Height = content rows + 2 (for top and bottom borders)
                    (lines.max(cursor_row + 1) + 2).max(3) as u16
            } else {
                0
            };

            let console_height = {
                let (console_content, _) = tui_console_content(
                    current_pane == TuiPane::AgentProjects,
                    &agent_panel,
                    agent_log_view.as_ref(),
                    feedback_buffer.as_str(),
                );
                tui_feedback_console_height(
                    size.height,
                    size.width,
                    console_content,
                    agent_log_view.is_some(),
                )
            };

            // Main layout: active pane, input area (if active), and feedback console
            let main_layout = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Min(0),
                    Constraint::Length(input_height),
                    Constraint::Length(console_height),
                ])
                .split(size);

            let content_area = main_layout[0];
            if current_pane == TuiPane::AgentProjects {
                render_tui_agent_panel(
                    f,
                    content_area,
                    &mut agent_panel,
                    &active_root,
                    true,
                    text_color,
                    c_highlight,
                );
            } else if current_pane == TuiPane::Models {
                render_tui_models_panel(
                    f,
                    content_area,
                    &mut models_panel,
                    text_color,
                    c_highlight,
                );
            } else if archive_view {
                let selected_idx = archive_state.selected();
                let col_width = content_area.width as usize;
                let entries = read_archived_task_entries(&board_dir).unwrap_or_default();
                let tasks: Vec<String> = entries
                    .iter()
                    .map(|entry| format!("- {}", task_display_text(entry)))
                    .collect();
                let display_tasks: Vec<String> = entries
                    .iter()
                    .enumerate()
                    .map(|(idx, entry)| {
                        format!(
                            "- {}",
                            task_tui_display_text(entry, Some(idx) == selected_idx)
                        )
                    })
                    .collect();
                let highlight_style = Style::default().fg(Color::Black).bg(c_highlight);
                let block = Block::default()
                    .title(" Archived - press A again to leave ")
                    .title(
                        Line::from(vec![Span::raw(format!(" {} ", tasks.len()))])
                            .alignment(Alignment::Right),
                    )
                    .borders(Borders::ALL)
                    .border_style(Style::default().fg(Color::Indexed(244)));

                let inner_area = block.inner(content_area);
                keep_selected_task_visible(
                    &display_tasks,
                    selected_idx,
                    &mut archive_scroll_offset,
                    inner_area.height as usize,
                    col_width,
                );

                let mut current_y = 0;
                for (idx, (t, entry)) in display_tasks
                    .iter()
                    .zip(entries.iter())
                    .enumerate()
                    .skip(archive_scroll_offset)
                {
                    let cleaned = t.strip_prefix("- ").unwrap_or(t);
                    let is_selected = Some(idx) == selected_idx;
                    let mut wrapped_content = if is_selected {
                        wrap_text(cleaned, col_width.saturating_sub(5))
                    } else {
                        cleaned.to_string()
                    };
                    if entry.has_subtasks {
                        wrapped_content.push_str(" >");
                    }

                    let line_count = wrapped_content.lines().count().max(1);
                    if current_y >= inner_area.height as usize {
                        break;
                    }

                    let visible_height =
                        (line_count as u16).min(inner_area.height.saturating_sub(current_y as u16));
                    let item_area = ratatui::layout::Rect {
                        x: inner_area.x,
                        y: inner_area.y + current_y as u16,
                        width: inner_area.width,
                        height: visible_height,
                    };
                    let style = if is_selected {
                        highlight_style
                    } else {
                        Style::default().fg(text_color)
                    };
                    let item_text = format!("{}. {}", idx + 1, wrapped_content);
                    f.render_widget(Paragraph::new(item_text).style(style), item_area);

                    current_y += line_count;
                    if inner_area.y + current_y as u16 >= content_area.height {
                        break;
                    }
                }

                f.render_widget(block, content_area);
            } else {
                let visible_boards = visible_tui_board_indices(backlog_visible);
                let column_count = visible_boards.len();
                let chunks = Layout::default()
                    .direction(Direction::Horizontal)
                    .constraints(vec![Constraint::Ratio(1, column_count as u32); column_count])
                    .split(content_area);

                for (column_index, board_index) in visible_boards.iter().copied().enumerate() {
                    let status = statuses[board_index];
                    let selected_idx = board_states[board_index].selected();
                    let col_width = (size.width / column_count as u16) as usize;
                    let entries = read_task_entries(&board_dir, status).unwrap_or_default();
                    let tasks: Vec<String> = entries
                        .iter()
                        .map(|entry| {
                            format!(
                                "- {}",
                                task_display_text_with_agent_flag(
                                    entry,
                                    status,
                                    &task_agent_session_states,
                                )
                            )
                        })
                        .collect();
                    let display_tasks: Vec<String> = entries
                        .iter()
                        .enumerate()
                        .map(|(idx, entry)| {
                            format!(
                                "- {}",
                                task_tui_display_text_with_agent_flag(
                                    entry,
                                    status,
                                    Some(idx) == selected_idx,
                                    &task_agent_session_states,
                                )
                            )
                        })
                        .collect();
                    let _items: Vec<ListItem> = tasks
                        .clone()
                        .into_iter()
                        .enumerate()
                        .map(|(idx, t)| {
                            let cleaned = t.replace("- ", "");

                            let (desc, meta) = if let Some(start) = cleaned.rfind(" (") {
                                if cleaned.ends_with(')') {
                                    (
                                        &cleaned[..start],
                                        Some(&cleaned[start + 2..cleaned.len() - 1]),
                                    )
                                } else {
                                    (&cleaned[..], None)
                                }
                            } else {
                                (&cleaned[..], None)
                            };

                            let mut line = Line::from(vec![
                                Span::raw(format!("{}. ", idx + 1)),
                                Span::raw(if Some(idx) == selected_idx {
                                    wrap_text(desc, col_width.saturating_sub(5))
                                } else {
                                    desc.to_string()
                                }),
                            ]);

                            if let Some(m) = meta {
                                line.spans.push(
                                    Span::raw(format!(" ({})", m)).style(
                                        Style::default().bg(Color::DarkGray).fg(Color::White),
                                    ),
                                );
                            }

                            ListItem::new(line)
                        })
                        .collect();

                    let task_focus_active =
                        matches!(current_mode, Mode::View | Mode::Reorganize)
                            && current_pane == TuiPane::Tasks;
                    let highlight_style = if task_focus_active {
                        Style::default().fg(Color::Black).bg(c_highlight)
                    } else {
                        // Use a more subtle highlight when in Input/Edit mode
                        Style::default().fg(Color::White).bg(Color::DarkGray)
                    };

                    let reorganizing = matches!(current_mode, Mode::Reorganize);
                    let task_list_inner = render_tui_task_column_header(
                        f,
                        chunks[column_index],
                        titles[board_index],
                        tasks.len(),
                        selected_board == board_index,
                        reorganizing,
                        colors[board_index],
                    );
                    keep_selected_task_visible(
                        &display_tasks,
                        selected_idx,
                        &mut board_scroll_offsets[board_index],
                        task_list_inner.height as usize,
                        col_width,
                    );

                    let mut current_y = 0;
                    for (idx, (t, entry)) in display_tasks
                        .iter()
                        .zip(entries.iter())
                        .enumerate()
                        .skip(board_scroll_offsets[board_index])
                    {
                        let cleaned = t.strip_prefix("- ").unwrap_or(t);
                        let is_selected = Some(idx) == selected_idx;

                        let style = if is_selected {
                            highlight_style
                        } else {
                            Style::default().fg(text_color)
                        };

                        let mut wrapped_content = if is_selected {
                            wrap_text(cleaned, col_width.saturating_sub(5))
                        } else {
                            cleaned.to_string()
                        };
                        if entry.has_subtasks {
                            wrapped_content.push_str(" >");
                        }

                        let line_count = wrapped_content.lines().count().max(1);
                        if current_y >= task_list_inner.height as usize {
                            break;
                        }

                        let visible_height = (line_count as u16)
                            .min(task_list_inner.height.saturating_sub(current_y as u16));
                        let item_area = ratatui::layout::Rect {
                            x: task_list_inner.x,
                            y: task_list_inner.y + current_y as u16,
                            width: task_list_inner.width,
                            height: visible_height,
                        };

                        let item_text = format!("{}. {}", idx + 1, wrapped_content);
                        f.render_widget(Paragraph::new(item_text).style(style), item_area);

                        current_y += line_count;
                        if current_y >= task_list_inner.height as usize {
                            break;
                        }
                    }
                }
            }

            if let Some(model_input) = model_input.as_ref() {
                let label = model_input.label();
                let input_text = format!("{}{}", label, model_input.input.value());
                let input_paragraph = Paragraph::new(input_text.as_str())
                    .block(
                        Block::default()
                            .borders(Borders::ALL)
                            .title("Models Input (Enter advances/saves, Esc cancels)"),
                    )
                    .style(Style::default().fg(Color::White));
                f.render_widget(input_paragraph, main_layout[1]);
                let cursor = label.chars().count() + model_input.input.visual_cursor();
                let input_inner = main_layout[1].inner(ratatui::layout::Margin {
                    horizontal: 1,
                    vertical: 1,
                });
                f.set_cursor_position(Position::new(
                    input_inner.x
                        + (cursor as u16).min(input_inner.width.saturating_sub(1)),
                    input_inner.y,
                ));
            } else if matches!(current_mode, Mode::Input) || matches!(current_mode, Mode::Edit) {
                let label = if matches!(current_mode, Mode::Input) {
                    if subtask_parent.is_some() {
                        " Add Subtask: "
                    } else {
                        " Add Task: "
                    }
                } else {
                    " Edit Task: "
                };
                let display_value = task_input.display_value();
                let input_text = format!("{}{}", label, display_value);
                // Subtract 2 for the borders of the block
                let available_width = size.width.saturating_sub(2) as usize;
                let input_lines = styled_task_input_lines(label, &task_input, available_width);
                let input_paragraph = Paragraph::new(input_lines)
                    .block(
                        Block::default()
                            .borders(Borders::ALL)
                            .title("Input Mode (Enter to save, Esc to cancel)"),
                    )
                    .style(Style::default().fg(Color::White));
                f.render_widget(input_paragraph, main_layout[1]);

                let (cursor_x, cursor_y) = input_cursor_offset_at(
                    &input_text,
                    available_width,
                    label.len()
                        + byte_index_at_char(&display_value, task_input.display_cursor()),
                );
                let input_inner = main_layout[1].inner(ratatui::layout::Margin {
                    horizontal: 1,
                    vertical: 1,
                });
                f.set_cursor_position(Position::new(
                    input_inner.x + cursor_x.min(input_inner.width.saturating_sub(1)),
                    input_inner.y + cursor_y.min(input_inner.height.saturating_sub(1)),
                ));
            }

            let (console_content, console_color) = tui_console_content(
                current_pane == TuiPane::AgentProjects,
                &agent_panel,
                agent_log_view.as_ref(),
                feedback_buffer.as_str(),
            );
            let feedback_area = *main_layout.last().unwrap();
            let wrapped_console_content = wrap_input_text(
                console_content,
                feedback_area.width.saturating_sub(2) as usize,
            );
            let feedback_paragraph = Paragraph::new(wrapped_console_content.as_str())
                .block(tui_console_block(
                    console_title.as_str(),
                    console_right_title.as_deref(),
                ))
                .style(Style::default().fg(console_color))
                .scroll((
                    tui_log_scroll_offset(
                        &wrapped_console_content,
                        feedback_area.height.saturating_sub(2),
                    ),
                    0,
                ));

            // The feedback area is always the last element of main_layout
            f.render_widget(feedback_paragraph, feedback_area);

            if matches!(current_mode, Mode::Help) {
                let help_text = "TUI Commands:\n\n\
                                 [Space]        - Create new task / toggle selected agent project\n\
                                 [n/+]          - Create subtask under selected task\n\
                                 [Enter]        - Open subtasks, edit selected task, or open selected agent project\n\
                                 [e]            - Edit selected task\n\
                                 [g]            - Cycle selected project's Git mode: off/commit/push\n\
                                 [s]            - Stop/resume linked task or displayed Agent Output session\n\
                                 [i]            - Take over linked/displayed live session, then auto-restart exec\n\
                                 [c]            - Open linked idle Doing, Done/blocked, or displayed session\n\
                                 [l]            - Toggle active/selected project's live/current agent output\n\
                                 [a]            - Move selected task to archive\n\
                                 [A]            - Toggle archive view\n\
                                 [b]            - Move selected task to backlog\n\
                                 [B]            - Show/hide backlog column\n\
                                 [Backspace]    - Return to parent board\n\
                                 [d/Del]        - Delete selected task\n\
                                 [Agent Del]    - Remove selected project after confirmation\n\
                                 [Tab]          - Toggle task board and agent projects\n\
                                 [Agent m]      - Cycle selected target\n\
                                 [M]            - Open Models from Tasks or Agent Projects\n\
                                 [Models n/r/a] - Add provider / discover models / manually add ID\n\
                                 [Models /]     - Search model names and IDs\n\
                                 [Models x/Del] - Remove selected non-built-in provider\n\
                                 [Models d/c]   - Set CLT default / explicitly set Codex default\n\
                                 [Arrows]       - Navigate boards, tasks, providers, and models\n\
                                 [PgUp/Dn Home/End] - Jump through Models lists\n\
                                 [r]            - Toggle sticky Reorganize mode (r/Esc exits)\n\
                                 [Shift+Arrows] - Reorder/Move tasks\n\
                                 [Ctrl-P/N]     - Reorder task Up/Down\n\
                                 [0, 1, 2, 3]   - Focus Backlog/To Do/Doing/Done\n\
                                 [Input Arrows]         - Move cursor in wrapped input\n\
                                 [Ctrl/Alt+Left/Right]  - Jump input cursor by word\n\
                                 [Ctrl+A/E/W/U/K]       - Edit input line\n\
                                 [h / ?]        - Toggle Help\n\
                                 [q]            - Quit";

                let area = f.area();
                let popover_width = area.width.min(70);
                let popover_height = area.height.min(27);
                let x = area.width.saturating_sub(popover_width) / 2;
                let y = area.height.saturating_sub(popover_height) / 2;

                let popover_area = ratatui::layout::Rect {
                    x,
                    y,
                    width: popover_width,
                    height: popover_height,
                };

                let help_paragraph = Paragraph::new(help_text)
                    .block(
                        Block::default()
                            .title(" Help ")
                            .borders(Borders::ALL)
                            .border_style(Style::default().fg(Color::Yellow)),
                    )
                    .style(Style::default().fg(Color::White));

                f.render_widget(help_paragraph, popover_area);
            }
        })?;

        #[allow(clippy::collapsible_if)]
        if event::poll(std::time::Duration::from_millis(100))? {
            match event::read()? {
                Event::Paste(content) if model_input.is_some() => {
                    if let Some(input) = model_input.as_mut() {
                        input.insert_paste(&content);
                    }
                }
                Event::Paste(content) if matches!(current_mode, Mode::Input | Mode::Edit) => {
                    task_input.insert_paste(content);
                }
                Event::Key(key) => {
                    let input_available_width = terminal.size()?.width.saturating_sub(2) as usize;
                    if let Some(removal) = pending_agent_project_removal.take() {
                        match key.code {
                            KeyCode::Char('y') | KeyCode::Char('Y') => {
                                feedback_buffer = match remove_tui_agent_project(
                                    &mut agent_panel,
                                    &active_root,
                                    &removal,
                                ) {
                                    Ok(message) => {
                                        last_agent_panel_refresh = Instant::now();
                                        message
                                    }
                                    Err(error) => format!("Error: {error}"),
                                };
                            }
                            KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => {
                                feedback_buffer = format!("Kept agent project: {}", removal.name);
                            }
                            _ => {
                                feedback_buffer = tui_agent_project_removal_prompt(&removal);
                                pending_agent_project_removal = Some(removal);
                            }
                        }
                        continue;
                    }
                    if awaiting_model_provider_choice {
                        match key.code {
                            KeyCode::Esc => {
                                awaiting_model_provider_choice = false;
                                feedback_buffer = "Provider selection cancelled".to_string();
                            }
                            KeyCode::Char(digit @ '1'..='4') => {
                                awaiting_model_provider_choice = false;
                                let index = digit as usize - '1' as usize;
                                feedback_buffer =
                                    match add_tui_model_provider_preset(&mut models_panel, index) {
                                        Ok(message) => message,
                                        Err(error) => format!("Error: {error}"),
                                    };
                            }
                            KeyCode::Char('5') => {
                                awaiting_model_provider_choice = false;
                                model_input = Some(TuiModelInput::custom_provider());
                                feedback_buffer = model_input
                                    .as_ref()
                                    .expect("custom provider input was just created")
                                    .guidance()
                                    .to_string();
                            }
                            _ => {
                                feedback_buffer = tui_models_provider_choice_prompt().to_string();
                            }
                        }
                        continue;
                    }
                    if let Some(input) = model_input.as_mut() {
                        match key.code {
                            KeyCode::Esc => {
                                model_input = None;
                                feedback_buffer = "Models input cancelled".to_string();
                            }
                            KeyCode::Enter => {
                                match submit_tui_model_input(input, &mut models_panel) {
                                    Ok(Some(message)) => {
                                        model_input = None;
                                        feedback_buffer = message;
                                    }
                                    Ok(None) => {
                                        feedback_buffer = input.guidance().to_string();
                                    }
                                    Err(error) => feedback_buffer = format!("Error: {error}"),
                                }
                            }
                            _ => {
                                let label = input.label();
                                handle_input_key(
                                    &mut input.input,
                                    key,
                                    label,
                                    input_available_width,
                                )
                            }
                        }
                        continue;
                    }
                    match current_mode {
                        Mode::View => {
                            if matches!(key.code, KeyCode::Tab | KeyCode::BackTab) {
                                let previous_pane = current_pane;
                                current_pane = if previous_pane == TuiPane::Models {
                                    models_return_pane
                                } else {
                                    tui_pane_after_tab(current_pane, active_board)
                                };
                                if current_pane == TuiPane::AgentProjects {
                                    if previous_pane == TuiPane::Tasks {
                                        agent_panel.select_project_for_path(&active_root);
                                    }
                                    sync_open_tui_agent_log_view(&agent_panel, &mut agent_log_view);
                                    if agent_panel_refresh.request(&active_root) {
                                        last_agent_panel_refresh = Instant::now();
                                    }
                                } else if current_pane == TuiPane::Tasks {
                                    let selected_task = selected_task_entry_in_board(
                                        &board_dir,
                                        statuses[selected_board],
                                        &board_states[selected_board],
                                    )
                                    .map(|(_, task)| task);
                                    sync_open_tui_task_log_view(
                                        &mut agent_panel,
                                        &active_root,
                                        statuses[selected_board],
                                        selected_task.as_ref(),
                                        &mut agent_log_view,
                                    );
                                    last_agent_log_refresh = Instant::now();
                                }
                                feedback_buffer = if current_pane == TuiPane::AgentProjects {
                                    tui_agent_panel_instructions().to_string()
                                } else {
                                    tui_task_board_instructions().to_string()
                                };
                            } else if matches!(key.code, KeyCode::Esc)
                                && agent_log_view.take().is_some()
                            {
                                feedback_buffer = "Closed agent output log".to_string();
                            } else if current_pane == TuiPane::Models {
                                match key.code {
                                    KeyCode::Esc | KeyCode::Char('M') => {
                                        current_pane = models_return_pane;
                                        feedback_buffer = if current_pane == TuiPane::AgentProjects
                                        {
                                            tui_agent_panel_instructions().to_string()
                                        } else {
                                            tui_task_board_instructions().to_string()
                                        };
                                    }
                                    KeyCode::Char('q') => break,
                                    KeyCode::Char('h')
                                    | KeyCode::Char('H')
                                    | KeyCode::Char('?') => current_mode = Mode::Help,
                                    KeyCode::Left => {
                                        models_panel.focus = TuiModelsFocus::Providers;
                                        feedback_buffer = tui_models_instructions().to_string();
                                    }
                                    KeyCode::Right => {
                                        models_panel.focus = TuiModelsFocus::Models;
                                        feedback_buffer = tui_models_instructions().to_string();
                                    }
                                    KeyCode::Up => models_panel.select_previous(),
                                    KeyCode::Down => models_panel.select_next(),
                                    KeyCode::PageUp => models_panel.select_page_up(),
                                    KeyCode::PageDown => models_panel.select_page_down(),
                                    KeyCode::Home => models_panel.select_first(),
                                    KeyCode::End => models_panel.select_last(),
                                    KeyCode::Char('/') => {
                                        models_panel.focus = TuiModelsFocus::Models;
                                        model_input = Some(TuiModelInput::search_models(
                                            models_panel.model_search.clone(),
                                        ));
                                        feedback_buffer = model_input
                                            .as_ref()
                                            .expect("model search input was just created")
                                            .guidance()
                                            .to_string();
                                    }
                                    KeyCode::Char(' ') => {
                                        feedback_buffer =
                                            match toggle_tui_models_enabled(&mut models_panel) {
                                                Ok(message) => message,
                                                Err(error) => format!("Error: {error}"),
                                            };
                                    }
                                    KeyCode::Char('x') | KeyCode::Char('X') | KeyCode::Delete => {
                                        feedback_buffer =
                                            match remove_tui_model_provider(&mut models_panel) {
                                                Ok(message) => message,
                                                Err(error) => format!("Error: {error}"),
                                            };
                                    }
                                    KeyCode::Char('f') | KeyCode::Char('F') => {
                                        models_panel.focus = TuiModelsFocus::Models;
                                        feedback_buffer =
                                            match toggle_tui_model_favorite(&mut models_panel) {
                                                Ok(message) => message,
                                                Err(error) => format!("Error: {error}"),
                                            };
                                    }
                                    KeyCode::Char('t') | KeyCode::Char('T') => {
                                        models_panel.focus = TuiModelsFocus::Models;
                                        feedback_buffer =
                                            match cycle_tui_model_reasoning(&mut models_panel) {
                                                Ok(message) => message,
                                                Err(error) => format!("Error: {error}"),
                                            };
                                    }
                                    KeyCode::Char('d') | KeyCode::Char('D') => {
                                        models_panel.focus = TuiModelsFocus::Models;
                                        feedback_buffer =
                                            match set_tui_model_default(&mut models_panel) {
                                                Ok(message) => message,
                                                Err(error) => format!("Error: {error}"),
                                            };
                                    }
                                    KeyCode::Char('c') | KeyCode::Char('C') => {
                                        models_panel.focus = TuiModelsFocus::Models;
                                        feedback_buffer =
                                            match set_tui_codex_default(&mut models_panel) {
                                                Ok(message) => message,
                                                Err(error) => format!("Error: {error}"),
                                            };
                                    }
                                    KeyCode::Char('a') | KeyCode::Char('A') => {
                                        if let Some(provider) = models_panel.selected_provider() {
                                            model_input =
                                                Some(TuiModelInput::add_model(provider.id.clone()));
                                            feedback_buffer =
                                                format!("Add a model ID for {}", provider.name);
                                        } else {
                                            feedback_buffer =
                                                "Add a provider before adding a model".to_string();
                                        }
                                    }
                                    KeyCode::Char('r') | KeyCode::Char('R') => {
                                        feedback_buffer =
                                            match discover_tui_provider_models(&mut models_panel) {
                                                Ok(message) => message,
                                                Err(error) => {
                                                    format!("Model discovery failed: {error}")
                                                }
                                            };
                                    }
                                    KeyCode::Char('n') | KeyCode::Char('N') => {
                                        awaiting_model_provider_choice = true;
                                        feedback_buffer =
                                            tui_models_provider_choice_prompt().to_string();
                                    }
                                    _ => feedback_buffer = tui_models_instructions().to_string(),
                                }
                            } else if current_pane == TuiPane::AgentProjects {
                                match key.code {
                                    KeyCode::Esc => {
                                        if active_board {
                                            current_pane = TuiPane::Tasks;
                                            feedback_buffer =
                                                tui_task_board_instructions().to_string();
                                        } else {
                                            feedback_buffer =
                                                TUI_NO_ACTIVE_BOARD_MESSAGE.to_string();
                                        }
                                    }
                                    KeyCode::Char('q') => break,
                                    KeyCode::Char('h')
                                    | KeyCode::Char('H')
                                    | KeyCode::Char('?') => {
                                        current_mode = Mode::Help;
                                    }
                                    KeyCode::Delete => {
                                        if let Some(removal) =
                                            selected_tui_agent_project_removal(&agent_panel)
                                        {
                                            agent_log_view = None;
                                            feedback_buffer =
                                                tui_agent_project_removal_prompt(&removal);
                                            pending_agent_project_removal = Some(removal);
                                        } else {
                                            feedback_buffer =
                                                "No registered project selected to remove"
                                                    .to_string();
                                        }
                                    }
                                    KeyCode::Enter => {
                                        if agent_panel
                                            .selected_current_project_registration()
                                            .is_some()
                                        {
                                            match register_selected_current_project(
                                                &mut agent_panel,
                                                &active_root,
                                            ) {
                                                Ok(message) => {
                                                    last_agent_panel_refresh = Instant::now();
                                                    feedback_buffer = message;
                                                }
                                                Err(e) => feedback_buffer = format!("Error: {}", e),
                                            }
                                            continue;
                                        }

                                        let Some(project) = agent_panel
                                            .selected_project()
                                            .map(|entry| entry.project.clone())
                                        else {
                                            feedback_buffer =
                                                "No registered project selected".to_string();
                                            continue;
                                        };

                                        match ensure_existing_board(&project.path) {
                                            Ok(true) => {}
                                            Ok(false) => {
                                                feedback_buffer = format!(
                                                    "Project is not initialized: {}",
                                                    project.path.display()
                                                );
                                                continue;
                                            }
                                            Err(error) => {
                                                feedback_buffer = format!(
                                                    "Failed to repair project board {}: {}",
                                                    project.path.display(),
                                                    error
                                                );
                                                continue;
                                            }
                                        }

                                        match std::env::set_current_dir(&project.path) {
                                            Ok(_) => {
                                                active_root = project.path.clone();
                                                task_agent_session_states.clear();
                                                if agent_panel_refresh.request(&active_root) {
                                                    last_agent_panel_refresh = Instant::now();
                                                } else {
                                                    last_agent_panel_refresh = Instant::now()
                                                        .checked_sub(
                                                            tui_agent_panel_refresh_interval(),
                                                        )
                                                        .unwrap_or_else(Instant::now);
                                                }
                                                active_board = true;
                                                board_stack.clear();
                                                board_stack.push(get_tasks_dir(&active_root));
                                                selected_board = TODO_BOARD_INDEX;
                                                for state in board_states.iter_mut() {
                                                    state.select(None);
                                                }
                                                board_scroll_offsets = [0usize; 4];
                                                archive_state.select(None);
                                                archive_scroll_offset = 0;
                                                archive_view = false;
                                                current_pane = TuiPane::Tasks;
                                                let board_dir = get_tasks_dir(&active_root);
                                                select_first_task_if_present_in_board(
                                                    &board_dir,
                                                    statuses[selected_board],
                                                    &mut board_states[selected_board],
                                                );
                                                feedback_buffer = match set_terminal_title(
                                                    &app_title(&active_root),
                                                ) {
                                                    Ok(_) => {
                                                        format!(
                                                            "Opened project board: {}",
                                                            project.name
                                                        )
                                                    }
                                                    Err(err) => {
                                                        format!(
                                                            "Opened project board: {}; failed to update title: {}",
                                                            project.name, err
                                                        )
                                                    }
                                                };
                                            }
                                            Err(err) => {
                                                feedback_buffer = format!(
                                                    "Failed to switch to {}: {}",
                                                    project.path.display(),
                                                    err
                                                );
                                            }
                                        }
                                    }
                                    KeyCode::Char(' ') => {
                                        if agent_panel
                                            .selected_current_project_registration()
                                            .is_some()
                                        {
                                            match register_selected_current_project(
                                                &mut agent_panel,
                                                &active_root,
                                            ) {
                                                Ok(message) => {
                                                    last_agent_panel_refresh = Instant::now();
                                                    feedback_buffer = message;
                                                }
                                                Err(e) => feedback_buffer = format!("Error: {}", e),
                                            }
                                            continue;
                                        }

                                        match toggle_selected_tui_agent_project(
                                            &mut agent_panel,
                                            &active_root,
                                        ) {
                                            Ok(message) => {
                                                last_agent_panel_refresh = Instant::now();
                                                feedback_buffer = message;
                                            }
                                            Err(e) => feedback_buffer = format!("Error: {}", e),
                                        }
                                    }
                                    KeyCode::Char('g') | KeyCode::Char('G') => {
                                        if agent_panel
                                            .selected_current_project_registration()
                                            .is_some()
                                        {
                                            feedback_buffer =
                                            "Register current project before changing its Git mode"
                                                .to_string();
                                            continue;
                                        }

                                        match cycle_selected_tui_agent_project_git_mode(
                                            &mut agent_panel,
                                            &active_root,
                                        ) {
                                            Ok(message) => {
                                                last_agent_panel_refresh = Instant::now();
                                                feedback_buffer = message;
                                            }
                                            Err(e) => feedback_buffer = format!("Error: {}", e),
                                        }
                                    }
                                    KeyCode::Char('m') => {
                                        if agent_panel
                                            .selected_current_project_registration()
                                            .is_some()
                                        {
                                            feedback_buffer =
                                            "Register current project before changing its Codex model"
                                                .to_string();
                                            continue;
                                        }

                                        match cycle_selected_tui_agent_codex_model(
                                            &mut agent_panel,
                                            &active_root,
                                        ) {
                                            Ok(message) => {
                                                last_agent_panel_refresh = Instant::now();
                                                feedback_buffer = message;
                                            }
                                            Err(e) => feedback_buffer = format!("Error: {}", e),
                                        }
                                    }
                                    KeyCode::Char('M') => {
                                        models_return_pane = tui_models_return_pane(current_pane);
                                        models_panel.refresh();
                                        current_pane = TuiPane::Models;
                                        feedback_buffer = tui_models_instructions().to_string();
                                    }
                                    KeyCode::Char('f') | KeyCode::Char('F') => {
                                        if agent_panel
                                            .selected_current_project_registration()
                                            .is_some()
                                        {
                                            feedback_buffer =
                                            "Register current project before changing Codex fast mode"
                                                .to_string();
                                            continue;
                                        }

                                        match toggle_selected_tui_agent_codex_fast(
                                            &mut agent_panel,
                                            &active_root,
                                        ) {
                                            Ok(message) => {
                                                last_agent_panel_refresh = Instant::now();
                                                feedback_buffer = message;
                                            }
                                            Err(e) => feedback_buffer = format!("Error: {}", e),
                                        }
                                    }
                                    KeyCode::Char('t') | KeyCode::Char('T') => {
                                        if agent_panel
                                            .selected_current_project_registration()
                                            .is_some()
                                        {
                                            feedback_buffer =
                                            "Register current project before changing Codex thinking"
                                                .to_string();
                                            continue;
                                        }

                                        match cycle_selected_tui_agent_codex_reasoning(
                                            &mut agent_panel,
                                            &active_root,
                                        ) {
                                            Ok(message) => {
                                                last_agent_panel_refresh = Instant::now();
                                                feedback_buffer = message;
                                            }
                                            Err(e) => feedback_buffer = format!("Error: {}", e),
                                        }
                                    }
                                    KeyCode::Char('r') | KeyCode::Char('R') => {
                                        feedback_buffer = match retry_selected_tui_agent_project(
                                            &mut agent_panel,
                                            &active_root,
                                        ) {
                                            Ok(message) => message,
                                            Err(error) => {
                                                format!("Unable to retry selected project: {error}")
                                            }
                                        };
                                        last_agent_panel_refresh = Instant::now();
                                    }
                                    KeyCode::Char('s') => {
                                        let target_result = if agent_log_view.is_some() {
                                            viewed_tui_codex_session_target(agent_log_view.as_ref())
                                        } else {
                                            selected_tui_agent_session_target(&agent_panel)
                                        };
                                        let target = match target_result {
                                            Ok(target) => target,
                                            Err(error) => {
                                                feedback_buffer = error.to_string();
                                                continue;
                                            }
                                        };
                                        feedback_buffer = match toggle_tui_codex_session_stop(
                                            target.project_id,
                                            &target.session_id,
                                        ) {
                                            Ok(message) => message,
                                            Err(error) => format!(
                                                "Unable to stop or resume the displayed Codex session: {error}"
                                            ),
                                        };
                                        agent_panel.refresh(&active_root);
                                        last_agent_panel_refresh = Instant::now();
                                    }
                                    KeyCode::Char('i') => {
                                        let label = agent_log_view
                                            .as_ref()
                                            .map(|view| view.project_name.clone())
                                            .unwrap_or_else(|| "the selected project".to_string());
                                        let target = match viewed_tui_codex_session_target(
                                            agent_log_view.as_ref(),
                                        ) {
                                            Ok(target) => target,
                                            Err(error) => {
                                                feedback_buffer = error.to_string();
                                                continue;
                                            }
                                        };
                                        match run_tui_codex_session_interrupt(
                                            &mut terminal,
                                            &mut terminal_session,
                                            &app_title(&active_root),
                                            &target,
                                            &label,
                                        ) {
                                            Ok(message) => {
                                                agent_log_view = None;
                                                feedback_buffer = message;
                                            }
                                            Err(error) if !terminal_session.active => {
                                                return Err(error);
                                            }
                                            Err(error) => {
                                                feedback_buffer = format!(
                                                    "Unable to interrupt the displayed Codex session: {error}"
                                                );
                                            }
                                        }
                                        agent_panel.refresh(&active_root);
                                        last_agent_panel_refresh = Instant::now();
                                        if active_board {
                                            normalize_board_selections_in_board(
                                                &board_dir,
                                                &statuses,
                                                &mut board_states,
                                            );
                                        }
                                    }
                                    KeyCode::Char('c') => {
                                        let label = agent_log_view
                                            .as_ref()
                                            .map(|view| view.project_name.clone())
                                            .unwrap_or_else(|| "the selected project".to_string());
                                        let target = match viewed_tui_codex_session_target(
                                            agent_log_view.as_ref(),
                                        ) {
                                            Ok(target) => target,
                                            Err(error) => {
                                                feedback_buffer = error.to_string();
                                                continue;
                                            }
                                        };
                                        agent_panel.refresh(&active_root);
                                        last_agent_panel_refresh = Instant::now();
                                        let availability =
                                            match tui_codex_session_availability_for_path(
                                                &mut agent_panel,
                                                &target.project_path,
                                                &target.session_id,
                                            ) {
                                                Ok(availability) => availability,
                                                Err(error) => {
                                                    feedback_buffer = format!(
                                                        "Unable to check the displayed Codex session: {error}"
                                                    );
                                                    continue;
                                                }
                                            };
                                        if availability
                                            == TuiCodexSessionAvailability::SelectedSessionBusy
                                        {
                                            feedback_buffer =
                                                "The displayed Codex session is active; press i to take it over interactively."
                                                    .to_string();
                                            continue;
                                        }
                                        let shares_project = availability
                                            == TuiCodexSessionAvailability::ProjectBusy;
                                        match run_tui_codex_session_continue(
                                            &mut terminal,
                                            &mut terminal_session,
                                            &app_title(&active_root),
                                            &target,
                                            &label,
                                            shares_project,
                                            false,
                                        ) {
                                            Ok(message) => {
                                                agent_log_view = None;
                                                feedback_buffer = message;
                                            }
                                            Err(error) if !terminal_session.active => {
                                                return Err(error);
                                            }
                                            Err(error) => {
                                                feedback_buffer = format!(
                                                    "Unable to continue the displayed Codex session: {error}"
                                                );
                                            }
                                        }
                                        agent_panel.refresh(&active_root);
                                        last_agent_panel_refresh = Instant::now();
                                        if active_board {
                                            normalize_board_selections_in_board(
                                                &board_dir,
                                                &statuses,
                                                &mut board_states,
                                            );
                                        }
                                    }
                                    KeyCode::Char('l') | KeyCode::Char('L') => {
                                        if agent_log_view.take().is_some() {
                                            feedback_buffer = "Closed agent output log".to_string();
                                            continue;
                                        }

                                        match selected_tui_agent_log_view(&agent_panel) {
                                            Ok(Some(log_view)) => {
                                                let output_kind = if log_view.is_live {
                                                    "live agent output"
                                                } else {
                                                    "latest agent output"
                                                };
                                                feedback_buffer = format!(
                                                    "Showing {output_kind} for {}",
                                                    log_view.project_name
                                                );
                                                agent_log_view = Some(log_view);
                                                last_agent_log_refresh = Instant::now();
                                            }
                                            Ok(None) => {
                                                feedback_buffer = if agent_panel
                                                    .selected_current_project_registration()
                                                    .is_some()
                                                {
                                                    "Register current project before viewing agent output"
                                                .to_string()
                                                } else {
                                                    "No agent output recorded for selected project"
                                                        .to_string()
                                                };
                                            }
                                            Err(e) => feedback_buffer = format!("Error: {}", e),
                                        }
                                    }
                                    KeyCode::Up => {
                                        agent_panel.select_previous();
                                        sync_open_tui_agent_log_view(
                                            &agent_panel,
                                            &mut agent_log_view,
                                        );
                                        last_agent_log_refresh = Instant::now();
                                    }
                                    KeyCode::Down => {
                                        agent_panel.select_next();
                                        sync_open_tui_agent_log_view(
                                            &agent_panel,
                                            &mut agent_log_view,
                                        );
                                        last_agent_log_refresh = Instant::now();
                                    }
                                    _ => {
                                        feedback_buffer =
                                            tui_agent_panel_instructions().to_string();
                                    }
                                }
                            } else if archive_view {
                                match key.code {
                                    KeyCode::Char('A') | KeyCode::Char('a')
                                        if key.modifiers.contains(KeyModifiers::SHIFT) =>
                                    {
                                        archive_view = false;
                                        archive_state.select(None);
                                        archive_scroll_offset = 0;
                                        feedback_buffer = "Returned to Kanban view".to_string();
                                    }
                                    KeyCode::Char('q') => break,
                                    KeyCode::Char('h')
                                    | KeyCode::Char('H')
                                    | KeyCode::Char('?') => {
                                        current_mode = Mode::Help;
                                    }
                                    KeyCode::Up => {
                                        let tasks = read_archived_task_entries(&board_dir)
                                            .unwrap_or_default();
                                        if !tasks.is_empty() {
                                            let i = archive_state.selected().unwrap_or(0);
                                            if i > 0 {
                                                archive_state.select(Some(i - 1));
                                            } else {
                                                archive_state.select(Some(tasks.len() - 1));
                                            }
                                        }
                                    }
                                    KeyCode::Down => {
                                        let tasks = read_archived_task_entries(&board_dir)
                                            .unwrap_or_default();
                                        if !tasks.is_empty() {
                                            let i = archive_state.selected().unwrap_or(0);
                                            if i < tasks.len() - 1 {
                                                archive_state.select(Some(i + 1));
                                            } else {
                                                archive_state.select(Some(0));
                                            }
                                        }
                                    }
                                    _ => {
                                        feedback_buffer =
                                            "Archive view is read-only. Press A again to leave."
                                                .to_string();
                                    }
                                }
                            } else if matches!(key.code, KeyCode::Char('M')) {
                                models_return_pane = tui_models_return_pane(current_pane);
                                models_panel.refresh();
                                current_pane = TuiPane::Models;
                                feedback_buffer = tui_models_instructions().to_string();
                            } else if let Some(direction) = tui_task_reorder_direction(&key) {
                                feedback_buffer = reorder_selected_tui_task(
                                    &board_dir,
                                    statuses[selected_board],
                                    &mut board_states[selected_board],
                                    direction,
                                );
                            } else if tui_toggles_reorganize_mode(&key) {
                                current_mode = Mode::Reorganize;
                                feedback_buffer =
                                "Reorganize mode active: use Arrows to move tasks; press r or Esc to exit."
                                    .to_string();
                            } else if tui_starts_subtask_input(&key) {
                                if let Some((idx, entry)) = selected_task_entry_in_board(
                                    &board_dir,
                                    statuses[selected_board],
                                    &board_states[selected_board],
                                ) {
                                    current_mode = Mode::Input;
                                    subtask_parent = Some((idx + 1, entry));
                                    task_input.reset();
                                    feedback_buffer =
                                        "Enter the new subtask description.".to_string();
                                } else {
                                    feedback_buffer =
                                        "Select a parent task before creating a subtask."
                                            .to_string();
                                }
                            } else if key.modifiers.contains(KeyModifiers::SHIFT) {
                                match key.code {
                                    KeyCode::Char('A') | KeyCode::Char('a') => {
                                        archive_view = true;
                                        current_mode = Mode::View;
                                        archive_scroll_offset = 0;
                                        select_first_archive_task_if_present_in_board(
                                            &board_dir,
                                            &mut archive_state,
                                        );
                                        feedback_buffer =
                                            "Archive view. Press A again to leave archive view."
                                                .to_string();
                                    }
                                    KeyCode::Char('B') | KeyCode::Char('b') => {
                                        feedback_buffer = toggle_tui_backlog_column(
                                            &board_dir,
                                            &mut board_states,
                                            &mut selected_board,
                                            &mut backlog_visible,
                                        );
                                    }
                                    KeyCode::Left => {
                                        feedback_buffer = move_selected_tui_task_between_boards(
                                            &board_dir,
                                            &statuses,
                                            &mut board_states,
                                            &mut selected_board,
                                            backlog_visible,
                                            TuiTaskBoardMoveDirection::Left,
                                        );
                                    }
                                    KeyCode::Right => {
                                        feedback_buffer = move_selected_tui_task_between_boards(
                                            &board_dir,
                                            &statuses,
                                            &mut board_states,
                                            &mut selected_board,
                                            backlog_visible,
                                            TuiTaskBoardMoveDirection::Right,
                                        );
                                    }
                                    _ => {}
                                }
                            } else if key.modifiers.contains(KeyModifiers::CONTROL)
                                || key.modifiers.contains(KeyModifiers::ALT)
                            {
                                // Other Alt/Ctrl modifiers are not used for moving tasks.
                                _ = ();
                            } else {
                                match key.code {
                                    KeyCode::Esc => {
                                        let state = &mut board_states[selected_board];
                                        state.select(None);
                                        feedback_buffer = "Task unselected".to_string();
                                    }
                                    KeyCode::Char('B') => {
                                        feedback_buffer = toggle_tui_backlog_column(
                                            &board_dir,
                                            &mut board_states,
                                            &mut selected_board,
                                            &mut backlog_visible,
                                        );
                                    }
                                    KeyCode::Char('b') => {
                                        feedback_buffer = match move_selected_tui_task_to_backlog(
                                            &board_dir,
                                            &statuses,
                                            &mut board_states,
                                            &mut selected_board,
                                            backlog_visible,
                                        ) {
                                            Ok(message) => message,
                                            Err(error) => format!("Error: {error}"),
                                        };
                                    }
                                    KeyCode::Char('a') => {
                                        feedback_buffer = match move_selected_tui_task_to_archive(
                                            &board_dir,
                                            &statuses,
                                            &mut board_states,
                                            selected_board,
                                        ) {
                                            Ok(message) => message,
                                            Err(error) => format!("Error: {error}"),
                                        };
                                    }
                                    KeyCode::Char('A') => {
                                        archive_view = true;
                                        current_mode = Mode::View;
                                        archive_scroll_offset = 0;
                                        select_first_archive_task_if_present_in_board(
                                            &board_dir,
                                            &mut archive_state,
                                        );
                                        feedback_buffer =
                                            "Archive view. Press A again to leave archive view."
                                                .to_string();
                                    }
                                    KeyCode::Char('s') => {
                                        let selected_status = statuses[selected_board];
                                        let Some((_, task)) = selected_task_entry_in_board(
                                            &board_dir,
                                            selected_status,
                                            &board_states[selected_board],
                                        ) else {
                                            feedback_buffer = "No task selected".to_string();
                                            continue;
                                        };
                                        let Some(session_id) = codex_session_for_task(&task) else {
                                            feedback_buffer =
                                                "No Codex session linked to this task.".to_string();
                                            continue;
                                        };
                                        agent_panel.refresh(&active_root);
                                        last_agent_panel_refresh = Instant::now();
                                        if !agent_panel.select_project_for_path(&active_root) {
                                            feedback_buffer =
                                                "Register this project before controlling its Codex session."
                                                    .to_string();
                                            continue;
                                        }
                                        let Some(project_id) = agent_panel
                                            .selected_project()
                                            .map(|selected| selected.project.id)
                                        else {
                                            feedback_buffer =
                                                "Register this project before controlling its Codex session."
                                                    .to_string();
                                            continue;
                                        };
                                        feedback_buffer = match toggle_tui_codex_session_stop(
                                            project_id,
                                            &session_id,
                                        ) {
                                            Ok(message) => message,
                                            Err(error) => format!(
                                                "Unable to stop or resume the Codex session: {error}"
                                            ),
                                        };
                                    }
                                    KeyCode::Char('i') => {
                                        let selected_status = statuses[selected_board];
                                        let Some((_, task)) = selected_task_entry_in_board(
                                            &board_dir,
                                            selected_status,
                                            &board_states[selected_board],
                                        ) else {
                                            feedback_buffer = "No task selected".to_string();
                                            continue;
                                        };
                                        let Some(session_id) = codex_session_for_task(&task) else {
                                            feedback_buffer =
                                                "No Codex session linked to this task.".to_string();
                                            continue;
                                        };
                                        agent_panel.refresh(&active_root);
                                        last_agent_panel_refresh = Instant::now();
                                        if !agent_panel.select_project_for_path(&active_root) {
                                            feedback_buffer =
                                                "Register this project before interrupting its Codex session."
                                                    .to_string();
                                            continue;
                                        }
                                        let Some(project) = agent_panel
                                            .selected_project()
                                            .map(|selected| selected.project.clone())
                                        else {
                                            feedback_buffer =
                                                "Register this project before interrupting its Codex session."
                                                    .to_string();
                                            continue;
                                        };
                                        let target =
                                            TuiCodexSessionTarget::new(&project, session_id);
                                        let label = task_display_text(&task);
                                        match run_tui_codex_session_interrupt(
                                            &mut terminal,
                                            &mut terminal_session,
                                            &app_title(&active_root),
                                            &target,
                                            &label,
                                        ) {
                                            Ok(message) => {
                                                agent_log_view = None;
                                                feedback_buffer = message;
                                            }
                                            Err(error) if !terminal_session.active => {
                                                return Err(error);
                                            }
                                            Err(error) => {
                                                feedback_buffer = format!(
                                                    "Unable to interrupt the Codex session: {error}"
                                                );
                                            }
                                        }
                                        agent_panel.refresh(&active_root);
                                        last_agent_panel_refresh = Instant::now();
                                        normalize_board_selections_in_board(
                                            &board_dir,
                                            &statuses,
                                            &mut board_states,
                                        );
                                    }
                                    KeyCode::Char('c') => {
                                        let selected_status = statuses[selected_board];
                                        let Some((_, task)) = selected_task_entry_in_board(
                                            &board_dir,
                                            selected_status,
                                            &board_states[selected_board],
                                        ) else {
                                            feedback_buffer = "No task selected".to_string();
                                            continue;
                                        };

                                        if !task_supports_interactive_codex_resume(
                                            selected_status,
                                            &task,
                                        ) {
                                            feedback_buffer =
                                                "Codex sessions can be resumed from linked Doing, Done, or blocked Todo tasks."
                                                    .to_string();
                                            continue;
                                        }

                                        let Some(session_id) = codex_session_for_task(&task) else {
                                            feedback_buffer =
                                                "No Codex session linked to this task.".to_string();
                                            continue;
                                        };
                                        agent_panel.refresh(&active_root);
                                        last_agent_panel_refresh = Instant::now();
                                        let availability =
                                            match tui_codex_session_availability_for_path(
                                                &mut agent_panel,
                                                &active_root,
                                                &session_id,
                                            ) {
                                                Ok(availability) => availability,
                                                Err(error) => {
                                                    feedback_buffer = format!(
                                                        "Unable to check whether the Codex session is available: {error}"
                                                    );
                                                    continue;
                                                }
                                            };
                                        if availability
                                            == TuiCodexSessionAvailability::SelectedSessionBusy
                                        {
                                            feedback_buffer =
                                                "This exact Codex session is already running or in an interactive handoff; stop or wait for it before resuming it again."
                                                    .to_string();
                                            continue;
                                        }
                                        let shares_project = availability
                                            == TuiCodexSessionAvailability::ProjectBusy;
                                        let Some(project) = agent_panel
                                            .selected_project()
                                            .map(|selected| selected.project.clone())
                                        else {
                                            feedback_buffer =
                                                "Register this project before resuming its Codex session."
                                                    .to_string();
                                            continue;
                                        };
                                        let target =
                                            TuiCodexSessionTarget::new(&project, session_id);
                                        let label = task_display_text(&task);
                                        match run_tui_codex_session_continue(
                                            &mut terminal,
                                            &mut terminal_session,
                                            &app_title(&active_root),
                                            &target,
                                            &label,
                                            shares_project,
                                            true,
                                        ) {
                                            Ok(message) => {
                                                agent_log_view = None;
                                                feedback_buffer = message;
                                            }
                                            Err(error) if !terminal_session.active => {
                                                return Err(error);
                                            }
                                            Err(error) => {
                                                feedback_buffer = format!("Error: {error}");
                                            }
                                        }
                                        agent_panel.refresh(&active_root);
                                        last_agent_panel_refresh = Instant::now();
                                        normalize_board_selections_in_board(
                                            &board_dir,
                                            &statuses,
                                            &mut board_states,
                                        );
                                    }
                                    KeyCode::Char('l') | KeyCode::Char('L') => {
                                        if agent_log_view.take().is_some() {
                                            feedback_buffer = "Closed agent output log".to_string();
                                            continue;
                                        }

                                        let selected_status = statuses[selected_board];
                                        let selected_task = selected_task_entry_in_board(
                                            &board_dir,
                                            selected_status,
                                            &board_states[selected_board],
                                        )
                                        .map(|(_, task)| task);

                                        agent_panel.refresh(&active_root);
                                        last_agent_panel_refresh = Instant::now();
                                        match selected_tui_task_or_project_log_view_for_path(
                                            &mut agent_panel,
                                            &active_root,
                                            selected_status,
                                            selected_task.as_ref(),
                                        ) {
                                            Ok(Some(log_view)) => {
                                                let output_kind = if log_view.is_live {
                                                    "live agent output"
                                                } else {
                                                    "recorded agent output"
                                                };
                                                feedback_buffer = format!(
                                                    "Showing {output_kind} for {}",
                                                    log_view.project_name
                                                );
                                                agent_log_view = Some(log_view);
                                                last_agent_log_refresh = Instant::now();
                                            }
                                            Ok(None) => {
                                                feedback_buffer = if agent_panel
                                                    .last_error
                                                    .is_some()
                                                {
                                                    agent_panel
                                                        .last_error
                                                        .clone()
                                                        .unwrap_or_default()
                                                } else if agent_panel
                                                    .selected_current_project_registration()
                                                    .is_some()
                                                {
                                                    "Register current project before viewing agent output"
                                                    .to_string()
                                                } else if selected_task.is_some() {
                                                    "No agent output recorded for selected task"
                                                        .to_string()
                                                } else {
                                                    "No agent output recorded for selected project"
                                                        .to_string()
                                                };
                                            }
                                            Err(e) => feedback_buffer = format!("Error: {}", e),
                                        }
                                    }
                                    KeyCode::Char('q') => break,
                                    KeyCode::Backspace => {
                                        if board_stack.len() > 1 {
                                            board_stack.pop();
                                            selected_board = TODO_BOARD_INDEX;
                                            for state in board_states.iter_mut() {
                                                state.select(None);
                                            }
                                            let parent_board = board_stack
                                                .last()
                                                .cloned()
                                                .unwrap_or_else(|| get_tasks_dir(&active_root));
                                            select_first_task_if_present_in_board(
                                                &parent_board,
                                                statuses[selected_board],
                                                &mut board_states[selected_board],
                                            );
                                            feedback_buffer =
                                                "Returned to parent board".to_string();
                                        } else {
                                            feedback_buffer =
                                                "Already at the top board".to_string();
                                        }
                                    }
                                    KeyCode::Enter => {
                                        if let Some((idx, entry)) = selected_task_entry_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &board_states[selected_board],
                                        ) {
                                            match &entry.source {
                                                TaskSource::Path { path, is_dir: true }
                                                    if entry.has_subtasks =>
                                                {
                                                    {
                                                        let _mutation_lock =
                                                            acquire_board_mutation_lock(path)?;
                                                        ensure_board_store(path)?;
                                                    }
                                                    board_stack.push(path.clone());
                                                    selected_board = TODO_BOARD_INDEX;
                                                    for state in board_states.iter_mut() {
                                                        state.select(None);
                                                    }
                                                    select_first_task_if_present_in_board(
                                                        path,
                                                        statuses[selected_board],
                                                        &mut board_states[selected_board],
                                                    );
                                                    feedback_buffer =
                                                        "Opened subtask board".to_string();
                                                }
                                                _ => {
                                                    current_mode = Mode::Edit;
                                                    editing_task_idx = Some(idx + 1);
                                                    task_input = TaskInput::new(
                                                        task_content_without_recoverable_codex_session(
                                                            &entry.content,
                                                        ),
                                                    );
                                                }
                                            }
                                        } else {
                                            board_states[selected_board].select(None);
                                            current_mode = Mode::Input;
                                            subtask_parent = None;
                                            task_input.reset();
                                        }
                                    }
                                    KeyCode::Char('e') | KeyCode::Char('E') => {
                                        if let Some((idx, entry)) = selected_task_entry_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &board_states[selected_board],
                                        ) {
                                            current_mode = Mode::Edit;
                                            editing_task_idx = Some(idx + 1);
                                            task_input = TaskInput::new(
                                                task_content_without_recoverable_codex_session(
                                                    &entry.content,
                                                ),
                                            );
                                        } else {
                                            feedback_buffer = "No task selected".to_string();
                                        }
                                    }
                                    KeyCode::Char(' ') => {
                                        if selected_task_index_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &board_states[selected_board],
                                        )
                                        .is_none()
                                        {
                                            board_states[selected_board].select(None);
                                        }
                                        current_mode = Mode::Input;
                                        subtask_parent = None;
                                        task_input.reset();
                                    }
                                    KeyCode::Char('0') => {
                                        backlog_visible = true;
                                        selected_board = BACKLOG_BOARD_INDEX;
                                        for state in board_states.iter_mut() {
                                            state.select(None);
                                        }
                                        select_first_task_if_present_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &mut board_states[selected_board],
                                        );
                                        feedback_buffer =
                                            "Backlog column shown and focused.".to_string();
                                    }
                                    KeyCode::Char('1') => {
                                        selected_board = TODO_BOARD_INDEX;
                                        for state in board_states.iter_mut() {
                                            state.select(None);
                                        }
                                        select_first_task_if_present_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &mut board_states[selected_board],
                                        );
                                    }
                                    KeyCode::Char('2') => {
                                        selected_board = 1;
                                        for state in board_states.iter_mut() {
                                            state.select(None);
                                        }
                                        select_first_task_if_present_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &mut board_states[selected_board],
                                        );
                                    }
                                    KeyCode::Char('3') => {
                                        selected_board = DONE_BOARD_INDEX;
                                        for state in board_states.iter_mut() {
                                            state.select(None);
                                        }
                                        select_first_task_if_present_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &mut board_states[selected_board],
                                        );
                                    }
                                    KeyCode::Char('d') | KeyCode::Char('D') | KeyCode::Delete => {
                                        if let Some(idx) = selected_task_index_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &board_states[selected_board],
                                        ) {
                                            let status = statuses[selected_board];
                                            match delete_task_in_board(
                                                &board_dir,
                                                status,
                                                &(idx + 1).to_string(),
                                            ) {
                                                Ok(_) => {
                                                    feedback_buffer = format!(
                                                        "Deleted task {} from {}",
                                                        idx + 1,
                                                        status
                                                    );
                                                    board_states[selected_board].select(
                                                        if idx > 0 { Some(idx - 1) } else { None },
                                                    );
                                                }
                                                Err(e) => feedback_buffer = format!("Error: {}", e),
                                            }
                                        } else {
                                            board_states[selected_board].select(None);
                                            feedback_buffer =
                                                "No task selected to delete".to_string();
                                        }
                                    }
                                    KeyCode::Char('h')
                                    | KeyCode::Char('H')
                                    | KeyCode::Char('?') => {
                                        current_mode = Mode::Help;
                                    }
                                    KeyCode::Up => {
                                        let state = &mut board_states[selected_board];
                                        let tasks = read_tasks_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                        )
                                        .unwrap_or_default();
                                        if !tasks.is_empty() {
                                            let i = state.selected().unwrap_or(0);
                                            if i > 0 {
                                                state.select(Some(i - 1));
                                            } else {
                                                state.select(Some(tasks.len() - 1));
                                            }
                                        }
                                    }
                                    KeyCode::Down => {
                                        let state = &mut board_states[selected_board];
                                        let tasks = read_tasks_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                        )
                                        .unwrap_or_default();
                                        if !tasks.is_empty() {
                                            let i = state.selected().unwrap_or(0);
                                            if i < tasks.len() - 1 {
                                                state.select(Some(i + 1));
                                            } else {
                                                state.select(Some(0));
                                            }
                                        }
                                    }
                                    KeyCode::Left => {
                                        selected_board = wrapped_visible_tui_board(
                                            selected_board,
                                            backlog_visible,
                                            -1,
                                        );
                                        for state in board_states.iter_mut() {
                                            state.select(None);
                                        }
                                        select_first_task_if_present_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &mut board_states[selected_board],
                                        );
                                    }
                                    KeyCode::Right => {
                                        selected_board = wrapped_visible_tui_board(
                                            selected_board,
                                            backlog_visible,
                                            1,
                                        );
                                        for state in board_states.iter_mut() {
                                            state.select(None);
                                        }
                                        select_first_task_if_present_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &mut board_states[selected_board],
                                        );
                                    }
                                    KeyCode::Char(c) if c.is_ascii_digit() => {
                                        let new_pos = (c as u8 - b'0') as usize;
                                        if let Some(idx) = selected_task_index_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &board_states[selected_board],
                                        ) {
                                            if new_pos > 0 {
                                                match reorder_task_in_board(
                                                    &board_dir,
                                                    statuses[selected_board],
                                                    idx,
                                                    new_pos - 1,
                                                ) {
                                                    Ok(_) => {
                                                        feedback_buffer = format!(
                                                            "Reordered task to position {}",
                                                            new_pos
                                                        )
                                                    }
                                                    Err(e) => {
                                                        feedback_buffer = format!("Error: {}", e)
                                                    }
                                                }
                                            }
                                        } else {
                                            board_states[selected_board].select(None);
                                            feedback_buffer = "No task selected".to_string();
                                        }
                                    }
                                    _ => {}
                                }
                            }
                        }
                        Mode::Reorganize => match tui_reorganize_input(&key) {
                            TuiReorganizeInput::Exit => {
                                current_mode = Mode::View;
                                feedback_buffer = "Reorganize mode exited.".to_string();
                            }
                            TuiReorganizeInput::Move(direction) => {
                                feedback_buffer = reorganize_selected_tui_task(
                                    &board_dir,
                                    &statuses,
                                    &mut board_states,
                                    &mut selected_board,
                                    backlog_visible,
                                    direction,
                                );
                            }
                            TuiReorganizeInput::Ignore => {
                                feedback_buffer = "Reorganize mode active: use Arrows to move tasks; press r or Esc to exit.".to_string();
                            }
                        },
                        Mode::Help => match key.code {
                            KeyCode::Enter
                            | KeyCode::Esc
                            | KeyCode::Char('h')
                            | KeyCode::Char('H')
                            | KeyCode::Char('?') => {
                                current_mode = Mode::View;
                            }
                            _ => {}
                        },
                        Mode::Input if tui_cancels_task_prompt(&key) => {
                            current_mode = Mode::View;
                            subtask_parent = None;
                            task_input.reset();
                        }
                        Mode::Input => match key.code {
                            KeyCode::Enter => {
                                let task_value = task_input.submitted_value();
                                if !task_value.trim().is_empty() {
                                    if let Some((parent_idx, expected_parent)) =
                                        subtask_parent.as_ref()
                                    {
                                        match insert_subtask_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            *parent_idx,
                                            expected_parent,
                                            &task_value,
                                            None,
                                        ) {
                                            Ok(subtask_board) => {
                                                board_stack.push(subtask_board.clone());
                                                selected_board = TODO_BOARD_INDEX;
                                                for state in board_states.iter_mut() {
                                                    state.select(None);
                                                }
                                                select_last_task_if_present_in_board(
                                                    &subtask_board,
                                                    statuses[selected_board],
                                                    &mut board_states[selected_board],
                                                );
                                                feedback_buffer =
                                                    "Subtask added and nested board opened."
                                                        .to_string();
                                            }
                                            Err(e) => feedback_buffer = format!("Error: {}", e),
                                        }
                                    } else {
                                        match insert_task_at_selection_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            &board_states[selected_board],
                                            &task_value,
                                            None,
                                        ) {
                                            Ok(_) => {
                                                feedback_buffer =
                                                    "Task added successfully.".to_string()
                                            }
                                            Err(e) => feedback_buffer = format!("Error: {}", e),
                                        }
                                    }
                                } else {
                                    feedback_buffer =
                                        "Task description cannot be empty.".to_string();
                                }
                                current_mode = Mode::View;
                                subtask_parent = None;
                                task_input.reset();
                            }
                            _ => {
                                let label = if subtask_parent.is_some() {
                                    " Add Subtask: "
                                } else {
                                    " Add Task: "
                                };
                                handle_input_key(
                                    &mut task_input.input,
                                    key,
                                    label,
                                    input_available_width,
                                )
                            }
                        },
                        Mode::Edit if tui_cancels_task_prompt(&key) => {
                            current_mode = Mode::View;
                            task_input.reset();
                            editing_task_idx = None;
                        }
                        Mode::Edit => match key.code {
                            KeyCode::Enter => {
                                let task_value = task_input.submitted_value();
                                if !task_value.trim().is_empty() {
                                    if let Some(idx) = editing_task_idx {
                                        match update_task_in_board(
                                            &board_dir,
                                            statuses[selected_board],
                                            idx,
                                            &task_value,
                                        ) {
                                            Ok(_) => {
                                                feedback_buffer =
                                                    format!("Task {} updated successfully.", idx)
                                            }
                                            Err(e) => feedback_buffer = format!("Error: {}", e),
                                        }
                                    }
                                } else {
                                    feedback_buffer =
                                        "Task description cannot be empty.".to_string();
                                }
                                current_mode = Mode::View;
                                task_input.reset();
                                editing_task_idx = None;
                            }
                            _ => handle_input_key(
                                &mut task_input.input,
                                key,
                                " Edit Task: ",
                                input_available_width,
                            ),
                        },
                    }
                }
                _ => {}
            }

            if agent_log_view.is_some()
                && current_pane == TuiPane::Tasks
                && active_board
                && !archive_view
                && matches!(current_mode, Mode::View)
            {
                let selected_task = selected_task_entry_in_board(
                    &board_dir,
                    statuses[selected_board],
                    &board_states[selected_board],
                )
                .map(|(_, task)| task);
                sync_open_tui_task_log_view(
                    &mut agent_panel,
                    &active_root,
                    statuses[selected_board],
                    selected_task.as_ref(),
                    &mut agent_log_view,
                );
                last_agent_log_refresh = Instant::now();
            }
        }
    }

    Ok(active_root)
}

fn init_tasks(root: &Path, folders: bool) -> Result<()> {
    let tasks_dir = get_tasks_dir(root);
    let tasks_dir_existed = tasks_dir.exists();
    let _mutation_lock = acquire_board_mutation_lock(&tasks_dir)?;
    if !tasks_dir_existed {
        fs::create_dir_all(&tasks_dir).context("Failed to create tasks directory")?;
        println!("Created directory: {:?}", tasks_dir);
    }

    let directory_mode = folders
        || TASK_STATUSES
            .iter()
            .any(|status| tasks_dir.join(status).is_dir());

    for status in TASK_STATUSES {
        let dir_path = tasks_dir.join(status);
        let file_path = tasks_dir.join(status_filename(status)?);
        if dir_path.is_dir() {
            println!("Directory already exists: {:?}", dir_path);
        } else if file_path.exists() {
            println!("File already exists: {:?}", file_path);
        } else if directory_mode {
            fs::create_dir_all(&dir_path)
                .context(format!("Failed to create directory {:?}", dir_path))?;
            println!("Created directory: {:?}", dir_path);
        } else {
            let mut file = fs::File::create(&file_path)
                .context(format!("Failed to create file {:?}", file_path))?;
            file.write_all(status_header(status)?.as_bytes())
                .context(format!("Failed to write to file {:?}", file_path))?;
            println!("Created file: {:?}", file_path);
        }
    }

    println!("Initialization complete.");
    Ok(())
}

