        assert_eq!(
            store
                .lease_for_project_blocking(project_id)
                .unwrap()
                .unwrap()
                .holder,
            tui_holder
        );

        assert!(
            store
                .adopt_interactive_guardian_blocking(
                    project_id,
                    Some("session-123"),
                    tui_holder,
                    guardian_holder,
                    60,
                )
                .unwrap()
        );
        let control = store
            .session_control_blocking(project_id, "session-123")
            .unwrap()
            .unwrap();
