        assert!(
            store
                .reserve_and_claim_worker_blocking(
                    reservation("scheduler"),
                    std::process::id(),
                    "102",
                )
                .unwrap()
        );
        let worker = store.list_active_workers_blocking().unwrap().remove(0);
